test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('memisahkan ribuan dengan titik', () {
    expect(
      rupiah(1000),
      equals('Rp1.000'),
      reason: 'Seribu ditulis Rp1.000, pisahkan tiap tiga angka dengan titik.',
    );
    expect(
      rupiah(1500),
      equals('Rp1.500'),
      reason: 'Seribu lima ratus ditulis Rp1.500, bukan Rp1500 atau Rp1,500.',
    );
    expect(
      rupiah(9876),
      equals('Rp9.876'),
      reason: 'Empat digit selalu memakai tepat satu titik pemisah.',
    );
  });
  test('bilangan di bawah seribu tanpa pemisah', () {
    expect(
      rupiah(999),
      equals('Rp999'),
      reason: 'Di bawah seribu tidak perlu titik, langsung Rp999.',
    );
    expect(
      rupiah(1),
      equals('Rp1'),
      reason: 'Satu digit cukup ditempel langsung setelah Rp.',
    );
    expect(
      rupiah(123),
      equals('Rp123'),
      reason: 'Tiga digit belum butuh pemisah ribuan.',
    );
  });
  test('kelipatan seribu tepat', () {
    expect(
      rupiah(2000),
      equals('Rp2.000'),
      reason: 'Dua ribu ditulis Rp2.000 dengan tiga nol di belakang titik.',
    );
    expect(
      rupiah(10000),
      equals('Rp10.000'),
      reason: 'Sepuluh ribu memakai satu titik menjadi Rp10.000.',
    );
    expect(
      rupiah(100000),
      equals('Rp100.000'),
      reason: 'Seratus ribu memakai satu titik menjadi Rp100.000.',
    );
  });
  test('nol ditampilkan sebagai Rp0', () {
    expect(
      rupiah(0),
      equals('Rp0'),
      reason: 'Nol tetap ditampilkan sebagai angka Rp0.',
    );
    expect(
      rupiah(0),
      contains('0'),
      reason: 'Hasil untuk nol harus memuat karakter angka 0.',
    );
    expect(
      rupiah(0),
      hasLength(3),
      reason: 'Teks Rp0 panjangnya tepat tiga karakter.',
    );
  });
  test('bilangan negatif diawali minus', () {
    expect(
      rupiah(-500),
      equals('-Rp500'),
      reason: 'Tanda minus ditulis sebelum Rp, bukan sesudahnya.',
    );
    expect(
      rupiah(-1),
      equals('-Rp1'),
      reason: 'Negatif satu digit tetap memakai awalan -Rp.',
    );
    expect(
      rupiah(-999),
      equals('-Rp999'),
      reason: 'Negatif di bawah seribu tidak memakai titik.',
    );
  });
  test('lebih dari satu pemisah', () {
    expect(
      rupiah(1234567),
      equals('Rp1.234.567'),
      reason: 'Jutaan memakai dua titik menjadi Rp1.234.567.',
    );
    expect(
      rupiah(1000000),
      equals('Rp1.000.000'),
      reason: 'Satu juta ditulis Rp1.000.000.',
    );
    expect(
      rupiah(123456789),
      equals('Rp123.456.789'),
      reason: 'Ratusan juta memakai dua titik pemisah.',
    );
  });
  test('negatif dengan banyak digit', () {
    expect(
      rupiah(-1500),
      equals('-Rp1.500'),
      reason: 'Contoh di brief: -1500 menjadi -Rp1.500.',
    );
    expect(
      rupiah(-1234567),
      equals('-Rp1.234.567'),
      reason: 'Negatif jutaan memakai minus lalu dua titik.',
    );
    expect(
      rupiah(-1000000),
      equals('-Rp1.000.000'),
      reason: 'Negatif satu juta memakai minus lalu dua titik.',
    );
  });
}

