test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('contoh klasik dua belas petak', () {
    expect(tampungAir([0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1]), equals(6));
  });

  test('cekungan dalam di tengah', () {
    expect(tampungAir([4, 2, 0, 3, 2, 5]), equals(9));
  });

  test('satu lembah sederhana', () {
    expect(tampungAir([3, 0, 3]), equals(3));
  });

  test('tanjakan naik tidak menampung air', () {
    expect(tampungAir([0, 1, 2, 3]), equals(0));
  });

  test('list kosong menampung nol air', () {
    expect(tampungAir([]), equals(0));
  });

  test('satu petak dan tanjakan turun', () {
    expect(tampungAir([5]), equals(0),
        reason: 'Satu petak tidak punya penghalang kiri dan kanan, '
            'air langsung mengalir keluar.');
    expect(tampungAir([3, 2, 1, 0]), equals(0),
        reason: 'Tanjakan turun murni tidak membentuk cekungan.');
  });

  test('semua pematang sama tinggi', () {
    expect(tampungAir([2, 2, 2, 2]), equals(0),
        reason: 'Tanpa perbedaan tinggi tidak ada air yang tertahan.');
  });

  test('cekungan besar seratus ribu petak', () {
    final tinggi = List<int>.filled(100000, 1);
    tinggi[0] = 1000;
    tinggi[99999] = 1000;
    expect(tampungAir(tinggi), equals(999 * 99998),
        reason: 'Dua penunjuk O(n) sekali lintasan langsung selesai; '
            'cara naif memindai ulang kiri dan kanan tiap petak, '
            'sekitar n kuadrat langkah, dan tidak akan selesai tepat waktu.');
  }, timeout: Timeout(Duration(seconds: 10)));
}

