test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('contoh klasik sembilan tiang', () {
    expect(wadahTerbanyak([1, 8, 6, 2, 5, 4, 8, 3, 7]), equals(49));
  });

  test('dua tiang kembar', () {
    expect(wadahTerbanyak([1, 1]), equals(1));
  });

  test('ujung sama tinggi', () {
    expect(wadahTerbanyak([4, 3, 2, 1, 4]), equals(16));
  });

  test('puncak di tengah', () {
    expect(wadahTerbanyak([1, 2, 1]), equals(2));
  });

  test('tanjakan naik', () {
    expect(wadahTerbanyak([1, 2, 3, 4]), equals(4));
  });

  test('tanjakan turun', () {
    expect(wadahTerbanyak([4, 3, 2, 1]), equals(4));
  });

  test('tiang tertinggi berhimpit', () {
    expect(wadahTerbanyak([1, 5, 5, 1]), equals(5),
        reason: 'Lebar 1 dikali tinggi 5 menghasilkan 5; pasangan yang '
            'memakai tiang ujung hanya selebar 3 dikali 1. Pilih sisi yang '
            'lebih pendek dulu agar pasangan sempit tapi tinggi tidak terlewat.');
  });

  test('seratus ribu tiang acak terbatas', () {
    final tinggi = List<int>.generate(100000, (i) => (i * 7919) % 1000 + 1);
    final hasil = wadahTerbanyak(tinggi);
    expect(hasil, greaterThan(90000000),
        reason: 'Solusi dua pointer O(n) memindai sekali dari dua ujung; '
            'cara naif memeriksa sekitar 5 miliar pasangan dan tidak akan '
            'selesai tepat waktu.');
  }, timeout: Timeout(Duration(seconds: 10)));
}

