/// Ringkas [teks] agar panjangnya tidak melebihi [batas].
String ringkas(String teks, int batas) {
  // TODO: kerjakan di sini
  return '';
}

test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('teks pendek dikembalikan apa adanya', () {
    expect(
      ringkas('Halo dunia', 20),
      equals('Halo dunia'),
      reason: 'Teks yang muat dalam batas dikembalikan tanpa diubah.',
    );
    expect(
      ringkas('Halo', 10),
      equals('Halo'),
      reason: 'Teks pendek tidak perlu dipotong atau diberi titik-titik.',
    );
    expect(
      ringkas('Halo dunia', 10),
      equals('Halo dunia'),
      reason: 'Panjang yang pas sama dengan batas juga dikembalikan utuh.',
    );
  });
  test('memotong di antara kata', () {
    expect(
      ringkas('Selamat datang di kelas', 20),
      equals('Selamat datang di...'),
      reason: 'Potong di batas kata lalu tambahkan titik-titik.',
    );
    expect(
      ringkas('satu dua tiga empat', 13),
      equals('satu dua...'),
      reason: 'Kata yang terpotong dibuang utuh, bukan dipenggal.',
    );
    expect(
      ringkas('satu dua tiga empat', 13).length,
      lessThanOrEqualTo(13),
      reason: 'Hasil beserta titik-titiknya tidak boleh melebihi batas.',
    );
  });
  test('panjang hasil tidak melebihi batas', () {
    expect(
      ringkas('Selamat datang di kelas', 20).length,
      lessThanOrEqualTo(20),
      reason: 'Hasil untuk batas 20 panjangnya maksimal 20 karakter.',
    );
    expect(
      ringkas('Pemrograman', 6).length,
      lessThanOrEqualTo(6),
      reason: 'Hasil untuk batas 6 panjangnya maksimal 6 karakter.',
    );
    expect(
      ringkas('Halo dunia yang indah sekali', 10).length,
      lessThanOrEqualTo(10),
      reason: 'Hasil untuk batas 10 panjangnya maksimal 10 karakter.',
    );
  });
  test('kata tunggal yang panjang dipotong di tengah', () {
    expect(
      ringkas('Pemrograman', 6),
      equals('Pem...'),
      reason:
          'Contoh di brief: kata tunggal dipenggal lalu diberi titik-titik.',
    );
    expect(
      ringkas('abcdefghij', 7),
      equals('abcd...'),
      reason:
          'Tanpa spasi, potong tepat di sisa ruang lalu tambah titik-titik.',
    );
    expect(
      ringkas('Supercalifragilistic', 10),
      equals('Superca...'),
      reason: 'Kata sangat panjang dipenggal sepanjang ruang yang tersedia.',
    );
  });
  test('batas sangat kecil tidak menghasilkan titik-titik', () {
    expect(
      ringkas('Pemrograman', 3),
      equals('Pem'),
      reason: 'Contoh di brief: batas 3 hanya memotong tanpa titik-titik.',
    );
    expect(
      ringkas('Pemrograman', 2),
      equals('Pe'),
      reason: 'Batas 2 hanya memotong dua huruf pertama.',
    );
    expect(
      ringkas('Pemrograman', 1),
      equals('P'),
      reason: 'Batas 1 hanya memotong satu huruf pertama.',
    );
    expect(
      ringkas('Pemrograman', 3),
      isNot(contains('...')),
      reason: 'Batas 3 atau kurang tidak boleh memuat titik-titik.',
    );
  });
  test('spasi menggantung dibuang', () {
    expect(
      ringkas('Halo dunia', 8),
      equals('Halo...'),
      reason: 'Spasi sisa di ujung potongan dibuang sebelum titik-titik.',
    );
    expect(
      ringkas('Halo dunia', 8),
      isNot(contains(' ...')),
      reason: 'Tidak boleh ada spasi yang menggantung sebelum titik-titik.',
    );
    expect(
      ringkas('Halo dunia', 8).length,
      lessThanOrEqualTo(8),
      reason: 'Hasil setelah spasi dibuang tetap dalam batas.',
    );
  });
  test('spasi berurutan tidak merusak potongan', () {
    expect(
      ringkas('Halo  dunia besar', 12),
      equals('Halo...'),
      reason: 'Spasi ganda ikut dibuang saat mundur ke batas kata.',
    );
    expect(
      ringkas('Halo  dunia besar', 12).length,
      lessThanOrEqualTo(12),
      reason: 'Hasil dengan spasi ganda tetap dalam batas.',
    );
    expect(
      ringkas('Halo  dunia besar', 12),
      contains('...'),
      reason: 'Teks yang dipotong tetap diakhiri titik-titik.',
    );
  });
}

