test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('contoh bolak balik', () {
    expect(substringUnikTerpanjang('ABCCBA'), equals(3));
  });

  test('semua sama', () {
    expect(substringUnikTerpanjang('BBBB'), equals(1));
  });

  test('string kosong', () {
    expect(substringUnikTerpanjang(''), equals(0));
  });

  test('contoh kenangan', () {
    expect(substringUnikTerpanjang('KENANGAN'), equals(4));
  });

  test('satu huruf', () {
    expect(substringUnikTerpanjang('Q'), equals(1),
        reason: 'satu huruf berarti jawabannya 1');
  });

  test('semua beda', () {
    expect(substringUnikTerpanjang('ABCDEFG'), equals(7),
        reason: 'tidak ada yang berulang, jawabannya panjang string');
  });

  test('ulang di ujung', () {
    expect(substringUnikTerpanjang('ABCDA'), equals(4),
        reason: 'huruf pertama berulang di akhir, jendela terbaik panjang 4');
  });

  test('performa seratus ribu huruf', () {
    final sb = StringBuffer();
    for (var i = 0; i < 100000; i++) {
      sb.writeCharCode(65 + (i % 26));
    }
    expect(substringUnikTerpanjang(sb.toString()), equals(26),
        reason:
            'jendela geser linear O(n) selesai cepat, cara cek semua pasangan O(n kuadrat) tidak akan selesai');
  }, timeout: Timeout(Duration(seconds: 10)));
}

