      reason: 'Satu kolom dengan satu baris tetap menghasilkan satu peta.',
    );
  });
  test('memetakan kolom ke nama header', () {
    final hasil = bacaCsv('npm,nama\n2401,Andi\n2402,Budi');
    expect(
