    final hasil = bacaCsv('npm,nama\n2401010015,"Pramana, I Kadek"');
    expect(
      hasil,
      hasLength(1),
      reason: 'Baris dengan koma di dalam kutipan tetap dihitung satu baris.',
    );
    expect(
      hasil[0]['nama'],
      equals('Pramana, I Kadek'),
      reason: 'Koma di dalam tanda kutip adalah isi nama bukan pemisah kolom.',
    );
    expect(
      hasil[0]['npm'],
      equals('2401010015'),
      reason: 'Kolom pertama harus tetap terbaca walaupun kolom kedua dikutip.',
    );
  });
  test('teks kosong menghasilkan daftar kosong', () {
    expect(
      bacaCsv(''),
      isEmpty,
      reason: 'Teks kosong tidak punya header sehingga hasilnya daftar kosong.',
    );
    expect(
      bacaCsv('   '),
      isEmpty,
      reason: 'Teks berisi spasi saja dianggap kosong sehingga hasilnya daftar kosong.',
    );
    expect(
      bacaCsv('\n\n'),
      isEmpty,
      reason: 'Teks berisi baris kosong saja tidak punya data sehingga hasilnya daftar kosong.',
    );
  });
  test('baris kosong dilewati', () {
