      reason: 'Baris sebelum baris kosong harus tetap terbaca dengan benar.',
    );
    expect(
      hasil[1],
      equals({'a': '3', 'b': '4'}),
      reason: 'Baris sesudah baris kosong harus tetap terbaca dengan benar.',
    );
  });
  test('kutipan ganda di dalam kutipan', () {
    final hasil = bacaCsv('kata\n"Hei ""Bos"""');
    expect(
