      hasLength(1),
      reason: 'Baris yang dikutip harus tetap dihitung satu baris data.',
    );
    expect(
      hasil[0]['kata'],
      equals('Hei "Bos"'),
      reason:
          'Dua kutip berurutan di dalam kutipan berarti satu tanda kutip asli.',
