      reason: 'Nilai yang tidak ada harus menjadi string kosong bukan null.',
    );
    expect(
      () => bacaCsv('a,b\n1,2,3'),
      throwsFormatException,
      reason: 'Baris dengan kolom lebih banyak dari header bentuknya salah sehingga harus ditolak.',
    );
  });
}

