import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('menemukan dua kegiatan yang menimpa', () {
    final hasil = bentrok({
      'Basis Data': '09:00-10:30',
      'Pemrograman': '10:00-11:30',
      'Olahraga': '13:00-14:00',
    });
    expect(
      hasil,
      equals(['Basis Data', 'Pemrograman']),
      reason: 'Basis Data dan Pemrograman saling menimpa sehingga keduanya harus dilaporkan.',
    );
    expect(
      hasil,
      hasLength(2),
      reason: 'Olahraga tidak menimpa siapa pun sehingga hanya dua nama yang dilaporkan.',
    );
    expect(
      hasil,
      contains('Pemrograman'),
      reason: 'Pemrograman bertabrakan dengan Basis Data sehingga wajib ada di hasil.',
    );
  });
  test('jadwal yang bersambung tidak dihitung bentrok', () {
    expect(
      bentrok({'Apel': '09:00-10:00', 'Jeruk': '10:00-11:00'}),
      isEmpty,
      reason: 'Dua kegiatan yang bersambung tepat di jam sepuluh tidak saling menimpa.',
    );
    expect(
      bentrok({'Apel': '09:00-10:00', 'Jeruk': '10:00-11:00'}),
      hasLength(0),
      reason: 'Tidak ada tabrakan sehingga panjang hasilnya harus nol.',
    );
    expect(
      bentrok({'Apel': '09:00-10:00', 'Jeruk': '10:00-11:00'}),
      equals([]),
      reason: 'Jadwal berdampingan harus menghasilkan daftar kosong.',
    );
  });
  test('hasil terurut abjad tanpa pengulangan', () {
    final hasil = bentrok({
      'Kimia': '09:00-11:00',
      'Fisika': '10:00-12:00',
      'Biologi': '10:30-11:30',
    });
    expect(
      hasil,
      orderedEquals(['Biologi', 'Fisika', 'Kimia']),
      reason: 'Ketiga nama harus terurut abjad dari Biologi sampai Kimia.',
    );
    expect(
      hasil.first,
      equals('Biologi'),
      reason: 'Biologi paling awal menurut abjad sehingga harus menjadi yang pertama.',
    );
    expect(
      hasil.toSet(),
      hasLength(3),
      reason: 'Setiap nama hanya boleh muncul sekali walaupun bertabrakan dengan dua kegiatan.',
    );
  });
  test('jadwal tanpa bentrok menghasilkan daftar kosong', () {
    final hasil = bentrok({
      'Pagi': '07:00-08:00',
      'Siang': '12:00-13:00',
      'Sore': '16:00-17:00',
    });
    expect(
      hasil,
      isEmpty,
      reason: 'Semua kegiatan berjauhan sehingga tidak ada yang dilaporkan.',
    );
    expect(
      hasil,
      equals([]),
      reason: 'Tanpa tabrakan hasilnya harus daftar kosong persis.',
    );
    expect(
      bentrok({}),
      isEmpty,
      reason:
          'Jadwal kosong tidak punya pasangan sehingga hasilnya juga kosong.',
    );
  });
  test('bentuk jam yang salah ditolak', () {
    expect(
      () => bentrok({'A': '09:00'}),
      throwsFormatException,
      reason:
          'Rentang tanpa tanda pisah bentuknya salah sehingga harus ditolak.',
    );
    expect(
      () => bentrok({'A': '09.00-10.00'}),
      throwsFormatException,
      reason: 'Titik bukan pemisah jam yang sah sehingga harus ditolak.',
    );
    expect(
      () => bentrok({'A': 'pagi-siang'}),
      throwsFormatException,
      reason: 'Kata bukan jam yang sah sehingga harus ditolak dengan FormatException.',
    );
  });
  test('jam selesai sebelum jam mulai ditolak', () {
    expect(
      () => bentrok({'A': '11:00-10:00'}),
      throwsFormatException,
      reason: 'Jam selesai lebih awal dari mulai tidak masuk akal sehingga harus ditolak.',
    );
    expect(
      () => bentrok({'A': '10:00-10:00'}),
      throwsFormatException,
      reason: 'Jam selesai yang sama dengan mulai berarti durasi nol sehingga harus ditolak.',
    );
    expect(
      () => bentrok({'A': '23:00-00:30'}),
      throwsFormatException,
      reason:
          'Jam selesai keesokan hari tetap lebih kecil sehingga harus ditolak.',
    );
  });
  test('tiga kegiatan bertumpuk semuanya dilaporkan', () {
    final hasil = bentrok({
      'A': '09:00-12:00',
      'B': '10:00-11:00',
      'C': '10:30-13:00',
      'D': '15:00-16:00',
    });
    expect(
      hasil,
      equals(['A', 'B', 'C']),
      reason: 'Ketiga kegiatan pagi saling bertumpuk sehingga semuanya harus dilaporkan tanpa D.',
    );
    expect(
      hasil,
      hasLength(3),
      reason: 'Kegiatan D yang menyendiri tidak boleh ikut sehingga hasilnya tepat tiga nama.',
    );
    expect(
      hasil,
      containsAll(['A', 'B', 'C']),
      reason: 'Setiap kegiatan yang menimpa minimal satu lainnya wajib ada di hasil.',
    );
  });
}

