    expect(hitung('2 + 3 * 4'), closeTo(14, 1e-9));
    expect(hitung('20 - 6 / 3'), closeTo(18, 1e-9));
    expect(hitung('2 * 3 + 4 * 5'), closeTo(26, 1e-9));
    expect(hitung('10 / 2 - 3'), closeTo(2, 1e-9));
  });

  test('kurung mengubah urutan', () {
    expect(hitung('(2 + 3) * 4'), closeTo(20, 1e-9));
    expect(hitung('10 / (2 + 3)'), closeTo(2, 1e-9));
    expect(hitung('(10 - 4) / 2'), closeTo(3, 1e-9));
    expect(hitung('(8 - 3) * (2 + 1)'), closeTo(15, 1e-9));
  });

  test('ekspresi tidak sah ditolak', () {
    expect(() => hitung('2 +'), throwsFormatException);
    expect(() => hitung('(3 * 4'), throwsFormatException);
    expect(() => hitung(''), throwsFormatException);
    expect(() => hitung('   '), throwsFormatException);
    expect(() => hitung('1 / 0'), throwsFormatException);
    expect(() => hitung('2 & 3'), throwsFormatException);
  });

  test('kurung bersarang dan bilangan desimal', () {
    expect(
      hitung('((1 + 2) * (3 + 4))'),
      closeTo(21, 1e-9),
      reason: 'Kurung yang bersarang dihitung mulai dari yang paling dalam.',
    );
    expect(
      hitung('1.5 + 2.5'),
      closeTo(4.0, 1e-9),
      reason: 'Koma desimal ditulis dengan titik, lalu dijumlahkan biasa.',
    );
    expect(
      hitung('(0.5 + 0.25) * 4'),
      closeTo(3.0, 1e-9),
      reason: 'Desimal boleh berdiri di dalam kurung seperti bilangan bulat.',
    );
    expect(
      hitung('((2.5))'),
      closeTo(2.5, 1e-9),
      reason: 'Kurung ganda tanpa operator di dalamnya tidak mengubah nilai.',
    );
    expect(
      hitung('7 / 2'),
      closeTo(3.5, 1e-9),
      reason: 'Pembagian yang tidak habis menghasilkan pecahan desimal.',
    );
  });

  test('tanda minus sebagai awalan bilangan', () {
    expect(
      hitung('-5 + 3'),
      closeTo(-2, 1e-9),
      reason:
          'Minus di depan bilangan pertama dibaca sebagai bilangan negatif.',
    );
    expect(
      hitung('2 * (-3)'),
      closeTo(-6, 1e-9),
      reason: 'Bilangan negatif boleh berdiri di dalam kurung.',
    );
    expect(
      hitung('-2 * -3'),
      closeTo(6, 1e-9),
      reason: 'Dua bilangan negatif yang dikalikan menghasilkan positif.',
    );
    expect(
      hitung('3 + -2'),
      closeTo(1, 1e-9),
      reason:
          'Minus sesudah operator tambah tetap milik bilangan di belakangnya.',
    );
    expect(
      hitung('(-5 + 10) * -2'),
      closeTo(-10, 1e-9),
      reason:
          'Hasil kurung yang dikali bilangan negatif mengikuti aturan tanda.',
    );
  });
}

