    expect(urutkan({'b': [], 'a': []}), orderedEquals(['a', 'b']));
    expect(
      urutkan({'c': [], 'a': [], 'b': []}),
      orderedEquals(['a', 'b', 'c']),
    );
    expect(
      urutkan({'zebra': [], 'apel': [], 'mangga': []}),
      orderedEquals(['apel', 'mangga', 'zebra']),
    );
    expect(urutkan(<String, List<String>>{}), isEmpty);
  });

  test('setiap tugas muncul tepat sekali', () {
    final hasil = urutkan({
      'd': ['b', 'c'],
      'b': ['a'],
      'c': ['a'],
      'a': [],
    });
    expect(hasil.length, equals(4));
    expect(hasil.toSet().length, equals(4));
    expect(hasil, containsAll(['a', 'b', 'c', 'd']));
    expect(hasil.indexOf('a'), lessThan(hasil.indexOf('d')));
  });

  test('lingkaran ketergantungan ditolak', () {
    expect(
      () => urutkan({
        'a': ['a'],
      }),
      throwsStateError,
    );
    expect(
      () => urutkan({
        'a': ['b'],
        'b': ['a'],
      }),
      throwsStateError,
    );
    expect(
      () => urutkan({
        'a': ['c'],
        'b': ['a'],
        'c': ['b'],
      }),
      throwsStateError,
    );
    expect(
      () => urutkan({
        'a': [],
        'x': ['y'],
        'y': ['z'],
        'z': ['x'],
      }),
      throwsStateError,
    );
  });

  test('syarat yang tidak punya barisnya sendiri tetap ikut', () {
    expect(
      urutkan({
        'saji': ['masak'],
      }),
      orderedEquals(['masak', 'saji']),
    );
    expect(
      urutkan({
        'c': ['a', 'b'],
      }),
      orderedEquals(['a', 'b', 'c']),
    );
    final hasil = urutkan({
      'lapor': ['tulis', 'kumpul'],
      'tulis': [],
    });
    expect(hasil.length, equals(3));
    expect(hasil, containsAll(['lapor', 'tulis', 'kumpul']));
  });

  test('urutan tidak tergantung urutan penulisan', () {
    final pertama = urutkan({
      'a': [],
      'b': ['a'],
      'c': ['a'],
    });
    final kedua = urutkan({
      'c': ['a'],
      'b': ['a'],
      'a': [],
    });
    expect(
      pertama,
      equals(kedua),
      reason:
          'Map yang ditulis beda urutan harus menghasilkan urutan yang sama.',
    );
    expect(
      pertama,
      orderedEquals(['a', 'b', 'c']),
      reason: 'Syarat a keluar paling dulu, lalu b dan c menurut abjad.',
    );
    final ketiga = urutkan({
      'z': ['m'],
      'm': ['a'],
    });
    final keempat = urutkan({
      'm': ['a'],
      'z': ['m'],
    });
    expect(
      ketiga,
      equals(keempat),
      reason: 'Rantai yang dibalik urutan tulisnya tetap tersusun a, m, z.',
    );
  });

  test('tetap cepat untuk tugas yang banyak', () {
    final rantai = <String, List<String>>{
      for (var i = 0; i < 500; i++) 't$i': i == 0 ? <String>[] : ['t${i - 1}'],
    };
    final hasil = urutkan(rantai);
    expect(
      hasil.length,
      equals(500),
      reason: 'Rantai 500 tugas harus selesai semua tanpa ada yang hilang.',
    );
    expect(
      hasil.first,
      equals('t0'),
      reason: 'Tugas paling awal tanpa syarat keluar paling depan.',
    );
    expect(
      hasil.last,
      equals('t499'),
      reason:
          'Tugas paling akhir yang menunggu semuanya keluar paling belakang.',
    );
    final bebas = <String, List<String>>{
      for (var i = 99; i >= 0; i--) 't$i': <String>[],
    };
    expect(
      urutkan(bebas).first,
      equals('t0'),
      reason: 'Seratus tugas bebas tetap mulai dari nama yang paling awal abjadnya.',
    );
  });
}

