    expect(tungguHangat([73, 74, 75, 71, 69, 72, 76, 73]),
        equals([1, 1, 4, 2, 1, 1, 0, 0]));
  });

  test('naik terus', () {
    expect(tungguHangat([30, 40, 50, 60]), equals([1, 1, 1, 0]));
  });

  test('turun terus', () {
    expect(tungguHangat([60, 50, 40, 30]), equals([0, 0, 0, 0]));
  });

  test('list kosong', () {
    expect(tungguHangat([]), equals([]),
        reason: 'Saran: list kosong langsung menghasilkan list kosong.');
  });

  test('satu hari', () {
