    expect(lebihBesarBerikutnya([1, 2, 1]), equals([2, -1, 2]));
  });

  test('menurun penuh mencari lewat belokan', () {
    expect(lebihBesarBerikutnya([5, 4, 3, 2, 1]), equals([-1, 5, 5, 5, 5]));
  });

  test('menaik penuh tanpa belokan', () {
    expect(lebihBesarBerikutnya([1, 2, 3, 4]), equals([2, 3, 4, -1]));
  });

  test('list kosong', () {
    expect(lebihBesarBerikutnya([]), equals([]),
        reason: 'Saran: list kosong langsung menghasilkan list kosong.');
  });

  test('satu elemen', () {
    expect(lebihBesarBerikutnya([7]), equals([-1]),
        reason: 'Saran: satu elemen tidak boleh dipasangkan dengan dirinya sendiri.');
  });

  test('semua sama', () {
    expect(lebihBesarBerikutnya([2, 2, 2]), equals([-1, -1, -1]),
        reason: 'Saran: syaratnya tegas lebih besar, nilai sama tidak menyelesaikan penantian.');
  });

  test('duplikat campuran', () {
    expect(lebihBesarBerikutnya([3, 1, 3, 2]), equals([-1, 3, -1, 3]),
        reason: 'Saran: tiap duplikat menunggu pasangannya sendiri-sendiri.');
  });

  test('performa seratus ribu menurun', () {
    final n = 100000;
    final angka = List<int>.generate(n, (i) => n - i);
    final hasil = lebihBesarBerikutnya(angka);
    expect(hasil[0], equals(-1));
    expect(hasil[1], equals(n));
    expect(hasil.last, equals(n),
        reason: 'Saran: stack dua putaran O(n) langsung selesai; pindai melingkar tiap posisi O(n^2) tidak akan selesai.');
  }, timeout: Timeout(Duration(seconds: 30)));
