          'Versi pra-rilis selalu di bawah rilis yang sama, cek aturan dasar.',
    );
    expect(
      bandingkan('1.0.0', '1.0.0-alpha'),
      equals(1),
      reason: 'Rilis selalu di atas pra-rilisnya, cek arah sebaliknya.',
    );
    expect(
      bandingkan('2.0.0-rc.1', '2.0.0'),
      equals(-1),
      reason: 'Kandidat rilis pun tetap di bawah rilis final, cek aturan umum.',
    );
  });
  test('versi yang sama menghasilkan nol', () {
