    );
    expect(
      bandingkan('1.0.0-alpha', '1.0.0-alpha'),
      equals(0),
      reason:
          'Pra-rilis identik juga menghasilkan 0, cek kesetaraan pra-rilis.',
    );
    expect(
      bandingkan('1.0.0-alpha+build', '1.0.0-alpha+lain'),
      equals(0),
      reason: 'Metadata berbeda tidak merusak kesetaraan, cek versi sama bermetadata.',
    );
  });
  test('bentuk yang tidak sah ditolak', () {
    expect(
      () => bandingkan('1.2', '1.2.3'),
      throwsFormatException,
      reason: 'Versi tak lengkap hanya dua bagian, harus ditolak dengan FormatException.',
    );
    expect(
      () => bandingkan('01.2.3', '1.2.3'),
      throwsFormatException,
      reason: 'Angka berawalan nol tidak sah, harus ditolak dengan FormatException.',
    );
    expect(
      () => bandingkan('1.0.0-', '1.0.0'),
      throwsFormatException,
      reason:
          'Pra-rilis kosong tidak sah, harus ditolak dengan FormatException.',
    );
    expect(
      () => bandingkan('a.b.c', '1.0.0'),
      throwsFormatException,
      reason: 'Huruf di bagian angka tidak sah, harus ditolak dengan FormatException.',
    );
  });
  test('aturan pengenal pra-rilis', () {
    expect(
      bandingkan('1.0.0-alpha.1', '1.0.0-alpha.beta'),
      equals(-1),
      reason: 'Pengenal angka lebih kecil dari berhuruf, cek aturan jenis pengenal.',
    );
    expect(
      bandingkan('1.0.0-alpha.1', '1.0.0-alpha.2'),
      equals(-1),
      reason: 'Pengenal angka dibandingkan sebagai angka, cek urutan numerik.',
    );
    expect(
      bandingkan('1.0.0-alpha', '1.0.0-alpha.1'),
      equals(-1),
      reason: 'Pengenal lebih sedikit berarti lebih kecil, cek aturan panjang.',
    );
    expect(
      bandingkan('1.0.0-alpha.beta', '1.0.0-beta'),
      equals(-1),
      reason: 'Huruf dibandingkan menurut abjad, cek urutan alfabetis.',
    );
  });
  test('metadata setelah tanda tambah diabaikan', () {
    expect(
      bandingkan('1.0.0+build.1', '1.0.0+build.2'),
      equals(0),
      reason: 'Metadata berbeda tidak memengaruhi hasil, harus tetap sama.',
    );
    expect(
      bandingkan('1.0.0+abc', '1.0.0'),
      equals(0),
      reason:
          'Ada atau tidak ada metadata hasilnya sama, cek metadata diabaikan.',
    );
    expect(
      bandingkan('1.0.0-alpha+1', '1.0.0-alpha+2'),
      equals(0),
      reason: 'Metadata pada pra-rilis juga diabaikan, cek kombinasi keduanya.',
    );
  });
}

