/// Mengisi papan Sudoku 9x9 secara in place.
///
/// [papan] berisi angka 1 sampai 9, dengan 0 berarti sel kosong.
/// Mengembalikan true bila papan terpecahkan. Mengembalikan false bila
/// papan tak valid atau tak terpecahkan.
bool selesaikanSudoku(List<List<int>> papan) {
  // TODO: kerjakan di sini
  return true;
}

test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

List<List<int>> dariBaris(List<String> baris) {
  return baris.map((s) => s.split('').map(int.parse).toList()).toList();
}

bool papanSah(List<List<int>> papan) {
  for (var r = 0; r < 9; r++) {
    final lihat = <int>{};
    for (var c = 0; c < 9; c++) {
      final v = papan[r][c];
      if (v < 1 || v > 9 || !lihat.add(v)) return false;
    }
  }
  for (var c = 0; c < 9; c++) {
    final lihat = <int>{};
    for (var r = 0; r < 9; r++) {
      if (!lihat.add(papan[r][c])) return false;
    }
  }
  for (var br = 0; br < 3; br++) {
    for (var bc = 0; bc < 3; bc++) {
      final lihat = <int>{};
      for (var r = br * 3; r < br * 3 + 3; r++) {
        for (var c = bc * 3; c < bc * 3 + 3; c++) {
          if (!lihat.add(papan[r][c])) return false;
        }
      }
    }
  }
  return true;
}

void main() {
  test('papan mudah klasik terpecahkan', () {
    final papan = dariBaris([
      '530070000',
      '600195000',
      '098000060',
      '800060003',
      '400803001',
      '700020006',
      '060000280',
      '000419005',
      '000080079',
    ]);
    final ref = papan;
    expect(selesaikanSudoku(papan), isTrue);
    expect(identical(ref, papan), isTrue);
    expect(papan, equals(dariBaris([
      '534678912',
      '672195348',
      '198342567',
      '859761423',
      '426853791',
      '713924856',
      '961537284',
      '287419635',
      '345286179',
    ])));
  });

  test('papan selesai tidak berubah', () {
    final papan = dariBaris([
      '534678912',
      '672195348',
      '198342567',
      '859761423',
      '426853791',
      '713924856',
      '961537284',
      '287419635',
      '345286179',
    ]);
    expect(selesaikanSudoku(papan), isTrue);
    expect(papan[0], equals([5, 3, 4, 6, 7, 8, 9, 1, 2]));
  });

  test('angka ganda satu baris ditolak', () {
    final papan = dariBaris([
      '533070000',
      '600195000',
      '098000060',
      '800060003',
      '400803001',
      '700020006',
      '060000280',
      '000419005',
      '000080079',
    ]);
    expect(selesaikanSudoku(papan), isFalse);
  });

  test('papan valid tapi tak terpecahkan', () {
    final papan = dariBaris([
      '516849730',
      '000000002',
      '000000000',
      '000000000',
      '000000000',
      '000000000',
      '000000000',
      '000000000',
      '000000000',
    ]);
    expect(selesaikanSudoku(papan), isFalse);
  });

  test('satu sel kosong terisi', () {
    final papan = dariBaris([
      '034678912',
      '672195348',
      '198342567',
      '859761423',
      '426853791',
      '713924856',
      '961537284',
      '287419635',
      '345286179',
    ]);
    expect(selesaikanSudoku(papan), isTrue,
        reason: 'Saran: sel kosong tunggal hanya punya satu kandidat, '
            'langsung isi tanpa cabang.');
    expect(papan[0][0], equals(5));
  });

  test('angka di luar nol sampai sembilan ditolak', () {
    final papan = dariBaris([
      '530070000',
      '600195000',
      '098000060',
      '800060003',
      '400803001',
      '700020006',
      '060000280',
      '000419005',
      '000080079',
    ]);
    papan[0][0] = 12;
    expect(selesaikanSudoku(papan), isFalse,
        reason: 'Saran: angka di luar 1 sampai 9 bukan papan valid, '
            'tolak sebelum mencari.');
  });

  test('performa papan berat klasik', () {
    final papan = dariBaris([
      '800000000',
      '003600000',
      '070090200',
      '050007000',
      '000045700',
      '000100030',
      '001000068',
      '008500010',
      '090000400',
    ]);
    expect(selesaikanSudoku(papan), isTrue);
    expect(papanSah(papan), isTrue,
        reason: 'Backtracking dengan masker bit dan sel kandidat tersedikit '
            'menuntaskan papan berat dengan cepat; coba semua angka tanpa '
            'masker meledak secara eksponensial dan tidak selesai tepat waktu.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

