test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

List<List<String>> dariBaris(List<String> baris) {
  return baris.map((s) => s.split('').toList()).toList();
}

List<List<String>> papanContoh() {
  return dariBaris([
    '53..7....',
    '6..195...',
    '.98....6.',
    '8...6...3',
    '4..8.3..1',
    '7...2...6',
    '.6....28.',
    '...419..5',
    '....8..79',
  ]);
}

void main() {
  test('papan sebagian terisi valid', () {
    expect(sudokuValid(papanContoh()), isTrue);
  });

  test('duplikat satu baris tidak valid', () {
    final papan = papanContoh();
    papan[0][2] = '5';
    expect(sudokuValid(papan), isFalse);
  });

  test('duplikat satu kolom tidak valid', () {
    final papan = papanContoh();
    papan[2][0] = '8';
    expect(sudokuValid(papan), isFalse);
  });

  test('duplikat satu kotak tidak valid', () {
    final papan = papanContoh();
    papan[1][1] = '9';
    expect(sudokuValid(papan), isFalse);
  });

  test('papan kosong semua titik valid', () {
    final papan = dariBaris([
      '.........',
      '.........',
      '.........',
      '.........',
      '.........',
      '.........',
      '.........',
      '.........',
      '.........',
    ]);
    expect(sudokuValid(papan), isTrue);
  });

  test('satu sel angka tunggal valid', () {
    final papan = dariBaris([
      '.........',
      '.........',
      '.........',
      '....5....',
      '.........',
      '.........',
      '.........',
      '.........',
      '.........',
    ]);
    expect(sudokuValid(papan), isTrue,
        reason: 'Saran: satu angka tidak punya pasangan duplikat, '
            'papan langsung valid.');
  });

  test('karakter asing tidak valid', () {
    final papan = papanContoh();
    papan[4][4] = '0';
    expect(sudokuValid(papan), isFalse,
        reason: 'Saran: hanya angka 1 sampai 9 dan titik yang boleh masuk, '
            'karakter lain membuat papan tidak valid.');
  });

  test('performa dua ribu papan valid', () {
    final dasar = papanContoh();
    var cacah = 0;
    for (var i = 0; i < 2000; i++) {
      final salin = dasar.map((b) => List<String>.of(b)).toList();
      if (sudokuValid(salin)) cacah++;
    }
    expect(cacah, equals(2000),
        reason: 'Satu sapuan dengan himpunan kunci O(81) per papan langsung '
            'selesai; pasangan sel per baris atau kolom tiap papan butuh '
            'langkah jauh lebih banyak.');
  }, timeout: Timeout(Duration(seconds: 10)));
}

