import 'package:latih/solusi.dart';

void main() {
  test('pecahan rupiah biasa', () {
    expect(
      tukar(87000, [100000, 50000, 20000, 10000, 5000, 2000, 1000]),
      orderedEquals([50000, 20000, 10000, 5000, 2000]),
      reason: 'Contoh brief harus pas, cek kombinasi rupiah yang benar.',
    );
    expect(
      tukar(5000, [10000, 5000, 2000]),
      equals([5000]),
      reason: 'Pecahan pas satu lembar cukup, cek kasus sederhana.',
    );
    expect(
      tukar(15000, [10000, 5000]),
      orderedEquals([10000, 5000]),
      reason: 'Dua pecahan menyusun jumlahnya, cek urutan besar ke kecil.',
    );
  });
  test('jumlah nol dan pecahan yang pas', () {
    expect(
      tukar(0, [1000, 500]),
      isEmpty,
      reason: 'Jumlah nol menghasilkan daftar kosong, cek aturan nol.',
    );
    expect(
      tukar(6, [3]),
      orderedEquals([3, 3]),
      reason: 'Pecahan pas dipakai berulang, cek pemakaian berkali-kali.',
    );
    expect(
      tukar(10, [10]),
      equals([10]),
      reason: 'Satu pecahan sama dengan jumlah, cek kasus satu lembar.',
    );
  });
  test('jumlah yang tidak mungkin ditukar ditolak', () {
    expect(
      () => tukar(3, [2, 4]),
      throwsStateError,
      reason:
          'Jumlah ganjil tak tersusun dari genap, harus melempar StateError.',
    );
    expect(
      () => tukar(7, [3, 6]),
      throwsStateError,
      reason: 'Tujuh tak tersusun dari 3 dan 6, harus melempar StateError.',
    );
    expect(
      () => tukar(1, [2]),
      throwsStateError,
      reason: 'Pecahan lebih besar dari jumlah tak mungkin, harus melempar StateError.',
    );
  });
  test('masukan tidak sah ditolak', () {
    expect(
      () => tukar(1000, []),
      throwsArgumentError,
      reason: 'Daftar pecahan kosong tidak sah, harus melempar ArgumentError.',
    );
    expect(
      () => tukar(1000, [0, 500]),
      throwsArgumentError,
      reason: 'Pecahan nol tidak sah, harus melempar ArgumentError.',
    );
    expect(
      () => tukar(1000, [1000, -5]),
      throwsArgumentError,
      reason: 'Pecahan negatif tidak sah, harus melempar ArgumentError.',
    );
    expect(
      () => tukar(-5, [1000]),
      throwsArgumentError,
      reason: 'Jumlah negatif tidak sah, harus melempar ArgumentError.',
    );
  });
  test('hasilnya benar-benar berjumlah sama', () {
    final h = tukar(87000, [100000, 50000, 20000, 10000, 5000, 2000, 1000]);
    expect(
      h.fold<int>(0, (a, b) => a + b),
      equals(87000),
      reason: 'Total lembar harus sama dengan jumlah, cek penjumlahan hasil.',
    );
    expect(
      tukar(6, [1, 3, 4]).fold<int>(0, (a, b) => a + b),
      equals(6),
      reason: 'Hasil contoh jebakan tetap berjumlah 6, cek penjumlahan.',
    );
    expect(
      tukar(11, [1, 5, 7]).fold<int>(0, (a, b) => a + b),
      equals(11),
      reason: 'Kombinasi apa pun totalnya pas, cek penjumlahan umum.',
    );
  });
  test('daftar pecahan yang menjebak cara serakah', () {
    expect(
      tukar(6, [1, 3, 4]),
      orderedEquals([3, 3]),
      reason: 'Contoh brief butuh dua lembar bukan tiga, jangan pakai cara serakah.',
    );
    expect(
      tukar(6, [1, 3, 4]).length,
      equals(2),
      reason: 'Solusi optimal hanya dua lembar, cek jumlah lembar minimal.',
    );
    expect(
      tukar(10, [1, 3, 4]),
      hasLength(3),
      reason: 'Sepuluh optimal tiga lembar, serakah memberi empat jadi salah.',
    );
  });
  test('paling sedikit untuk setiap jumlah, bukan sebagian', () {
    expect(
      tukar(8, [1, 3, 4]).length,
      equals(2),
      reason: 'Delapan optimal 4+4 dua lembar, cek minimum tiap jumlah.',
    );
    expect(
      tukar(7, [1, 3, 4]),
      orderedEquals([4, 3]),
      reason: 'Tujuh optimal 4+3, cek susunan desc yang minimal.',
    );
    expect(
      tukar(9, [1, 3, 4]).length,
      equals(3),
      reason: 'Sembilan butuh tiga lembar, cek DP bottom-up menyeluruh.',
    );
    expect(
      tukar(12, [1, 3, 4]).length,
      equals(3),
      reason: 'Dua belas optimal tiga lembar 4+4+4, cek skala lebih besar.',
    );
  });
}

