/// Mengembalikan semua susunan n ratu yang tidak saling serang.
///
/// Tiap solusi berisi [n] string dengan panjang [n].
/// Huruf 'Q' menandai ratu dan '.' menandai petak kosong.
/// Untuk [n] yang nol atau negatif, kembalikan list kosong.
List<List<String>> pasangRatu(int n) {
  // TODO: kerjakan di sini
  return [];
}

test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

bool solusiSah(List<String> papan) {
  final n = papan.length;
  final kolomRatu = <int>[];
  for (final baris in papan) {
    if (baris.length != n) return false;
    var cacah = 0;
    var kolom = -1;
    for (var c = 0; c < n; c++) {
      final ch = baris[c];
      if (ch == 'Q') {
        cacah++;
        kolom = c;
      } else if (ch != '.') {
        return false;
      }
    }
    if (cacah != 1) return false;
    kolomRatu.add(kolom);
  }
  for (var i = 0; i < n; i++) {
    for (var j = i + 1; j < n; j++) {
      if (kolomRatu[i] == kolomRatu[j]) return false;
      if ((kolomRatu[i] - kolomRatu[j]).abs() == (i - j).abs()) return false;
    }
  }
  return true;
}

void main() {
  test('papan empat punya dua solusi', () {
    final hasil = pasangRatu(4);
    expect(hasil.length, equals(2));
    final kunci = hasil.map((s) => s.join('|')).toSet();
    expect(kunci.contains('.Q..|...Q|Q...|..Q.'), isTrue);
    expect(kunci.contains('..Q.|Q...|...Q|.Q..'), isTrue);
  });

  test('papan satu punya satu solusi', () {
    expect(pasangRatu(1), equals([
      ['Q']
    ]));
  });

  test('papan dua tanpa solusi', () {
    expect(pasangRatu(2), equals([]));
  });

  test('papan tiga tanpa solusi', () {
    expect(pasangRatu(3), equals([]));
  });

  test('nol atau negatif tanpa solusi', () {
    expect(pasangRatu(0), equals([]),
        reason: 'Saran: papan tanpa baris tidak menampung ratu, '
            'kembalikan list kosong.');
    expect(pasangRatu(-4), equals([]),
        reason: 'Saran: nilai negatif bukan ukuran papan yang sah, '
            'kembalikan list kosong.');
  });

  test('semua solusi papan lima valid', () {
    final hasil = pasangRatu(5);
    expect(hasil.length, equals(10));
    for (final solusi in hasil) {
      expect(solusiSah(solusi), isTrue,
          reason: 'Saran: tiap solusi wajib memuat satu ratu per baris '
              'tanpa serangan kolom atau diagonal.');
    }
  });

  test('performa papan sembilan', () {
    final hasil = pasangRatu(9);
    expect(hasil.length, equals(352));
    expect(solusiSah(hasil[0]), isTrue,
        reason: 'Backtracking satu ratu per baris dengan tiga himpunan '
            'menuntaskan 352 solusi dengan cepat; mencoba semua petak '
            'tanpa pelacak serangan meledak secara faktorial.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

