test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('kunci tunggal dan bersarang', () {
    expect(
      ambil({'a': 1}, 'a'),
      orderedEquals([1]),
      reason: 'Kunci tunggal langsung ketemu, cek penelusuran satu tingkat.',
    );
    expect(
      ambil({
        'a': {'b': 2},
      }, 'a.b'),
      orderedEquals([2]),
      reason: 'Jalur titik menelusuri bertingkat, cek navigasi map bersarang.',
    );
    expect(
      ambil({
        'a': {
          'b': {'c': 3},
        },
      }, 'a.b.c'),
      orderedEquals([3]),
      reason: 'Tiga tingkat harus sampai ke nilai, cek rantai lebih dalam.',
    );
    expect(
      ambil({
        'kelas': [
          {'nama': 'A'},
        ],
      }, 'kelas[0].nama'),
      orderedEquals(['A']),
      reason:
          'Gabungan kunci dan indeks menunjuk satu nilai, cek jalur campuran.',
    );
  });
  test('indeks daftar termasuk dari belakang', () {
    expect(
      ambil({
        'a': [10, 20, 30],
      }, 'a[0]'),
      orderedEquals([10]),
      reason: 'Indeks nol mengambil elemen pertama, cek indeks awal.',
    );
    expect(
      ambil({
        'a': [10, 20, 30],
      }, 'a[2]'),
      orderedEquals([30]),
      reason: 'Indeks dua mengambil elemen ketiga, cek indeks tengah.',
    );
    expect(
      ambil({
        'a': [10, 20, 30],
      }, 'a[-1]'),
      orderedEquals([30]),
      reason: 'Indeks minus satu berarti elemen terakhir, cek dari belakang.',
    );
    expect(
      ambil({
        'a': [10, 20, 30],
      }, 'a[-3]'),
      orderedEquals([10]),
      reason: 'Indeks minus tiga kembali ke awal, cek offset negatif.',
    );
  });
  test('bintang mengambil semuanya', () {
    expect(
      ambil({
        'a': [1, 2, 3],
      }, 'a[*]'),
      orderedEquals([1, 2, 3]),
      reason: 'Bintang kurung mengambil semua elemen, cek wildcard daftar.',
    );
    expect(
      ambil({
        'm': {'x': 1, 'y': 2},
      }, 'm.*'),
      unorderedEquals([1, 2]),
      reason: 'Bintang titik mengambil semua nilai map, cek wildcard map.',
    );
    expect(
      ambil({
        'kelas': [
          {'nama': 'A'},
          {'nama': 'B'},
        ],
      }, 'kelas[*].nama'),
      orderedEquals(['A', 'B']),
      reason:
          'Contoh brief menghasilkan dua nama, cek gabungan bintang dan kunci.',
    );
  });
  test('jalur yang tidak ada menghasilkan daftar kosong', () {
    expect(
      ambil({'a': 1}, 'b'),
      isEmpty,
      reason: 'Kunci tak dikenal bukan kesalahan, harus daftar kosong.',
    );
    expect(
      ambil({
        'a': [1],
      }, 'a[5]'),
      isEmpty,
      reason: 'Indeks di luar jangkauan bukan kesalahan, harus daftar kosong.',
    );
    expect(
      ambil({
        'a': {'b': 1},
      }, 'a.c'),
      isEmpty,
      reason: 'Cabang buntu di tengah menghasilkan kosong, cek rantai putus.',
    );
    expect(
      ambil({'a': 1}, ''),
      orderedEquals([
        {'a': 1},
      ]),
      reason: 'Jalur kosong mengembalikan data apa adanya, cek aturan khusus.',
    );
  });
  test('jalur rusak ditolak', () {
    expect(
      () => ambil({
        'a': [1],
      }, 'a[0'),
      throwsFormatException,
      reason: 'Kurung tak tertutup itu jalur rusak, harus FormatException.',
    );
    expect(
      () => ambil({'a': 1}, 'a..b'),
      throwsFormatException,
      reason: 'Titik ganda tidak sah, harus FormatException.',
    );
    expect(
      () => ambil({
        'a': [1],
      }, 'a[abc]'),
      throwsFormatException,
      reason: 'Isi kurung bukan angka atau bintang, harus FormatException.',
    );
    expect(
      () => ambil({'a': 1}, '.a'),
      throwsFormatException,
      reason: 'Titik di awal tidak sah, harus FormatException.',
    );
  });
  test('bintang berlapis menelusuri seluruh cabang', () {
    final data = {
      'kelas': [
        {
          'mahasiswa': [
            {'nama': 'A'},
            {'nama': 'B'},
          ],
        },
        {
          'mahasiswa': [
            {'nama': 'C'},
          ],
        },
      ],
    };
    expect(
      ambil(data, 'kelas[*].mahasiswa[*].nama'),
      orderedEquals(['A', 'B', 'C']),
      reason: 'Dua bintang menelusuri semua cabang, cek urutan penelusuran.',
    );
    expect(
      ambil({
        'a': [
          [1, 2],
          [3],
        ],
      }, 'a[*][*]'),
      orderedEquals([1, 2, 3]),
      reason: 'Bintang ganda pada daftar meratakan semuanya, cek bintang bertumpuk.',
    );
    expect(
      ambil({
        'm': {
          'p': {'q': 1},
          'r': {'q': 2},
        },
      }, 'm.*.q'),
      unorderedEquals([1, 2]),
      reason: 'Bintang map lalu kunci menjangkau tiap cabang, cek kombinasi.',
    );
  });
  test('null yang memang ada tetap ikut', () {
    expect(
      ambil({'a': null}, 'a'),
      orderedEquals([null]),
      reason:
          'Null asli harus ikut sebagai satu elemen, beda dengan tak ketemu.',
    );
    expect(
      ambil({'a': null}, 'a'),
      hasLength(1),
      reason: 'Daftar berisi null panjangnya satu bukan kosong, cek pembeda penting.',
    );
    expect(
      ambil({
        'a': {'b': null},
      }, 'a.b'),
      orderedEquals([null]),
      reason: 'Null bersarang pun tetap ikut, cek null di kedalaman.',
    );
    expect(
      ambil({
        'a': [null, 1],
      }, 'a[*]'),
      orderedEquals([null, 1]),
      reason: 'Bintang tidak menyaring null, cek null dalam daftar.',
    );
  });
}

