/// Kata dibentuk dari sel bersebelahan ke atas, bawah, kiri, atau kanan
/// dengan tiap sel dipakai sekali saja. Kata kosong selalu menghasilkan
/// false. Papan tidak diubah setelah fungsi selesai.
bool cariKata(List<List<String>> papan, String kata) {
  // TODO: kerjakan di sini
  return false;
}

test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

List<List<String>> papanContoh() {
  return [
    ['A', 'B', 'C', 'E'],
    ['S', 'F', 'C', 'S'],
    ['A', 'D', 'E', 'E'],
  ];
}

void main() {
  test('kata abcced ketemu', () {
    expect(cariKata(papanContoh(), 'ABCCED'), isTrue);
  });

  test('kata see ketemu', () {
    expect(cariKata(papanContoh(), 'SEE'), isTrue);
  });

  test('kata abcb tidak ketemu', () {
    expect(cariKata(papanContoh(), 'ABCB'), isFalse);
  });

  test('kata kosong tidak ketemu', () {
    expect(cariKata(papanContoh(), ''), isFalse);
  });

  test('kata lebih panjang dari sel tidak ketemu', () {
    expect(cariKata(papanContoh(), 'ABCDEFGHIJKLM'), isFalse);
  });

  test('papan satu kali satu', () {
    expect(cariKata([['A']], 'A'), isTrue,
        reason: 'Saran: satu sel cocok dengan kata satu huruf.');
    expect(cariKata([['A']], 'B'), isFalse,
        reason: 'Saran: huruf beda berarti kata tidak ketemu.');
  });

  test('papan tidak berubah setelah mencari', () {
    final papan = papanContoh();
    final sebelum = papan.map((b) => List<String>.of(b)).toList();
    cariKata(papan, 'ABCCED');
    cariKata(papan, 'ABCB');
    expect(papan, equals(sebelum),
        reason: 'Saran: tanda kunjung wajib dikembalikan, '
            'papan harus sama seperti semula.');
  });

  test('performa papan tiga ratus enam belas kali tiga ratus enam belas', () {
    const n = 316;
    final papan = List<List<String>>.generate(
        n, (_) => List<String>.filled(n, 'A'));
    expect(cariKata(papan, 'AAAB'), isFalse,
        reason: 'DFS dengan tanda kunjung dan pemangkasan huruf pertama '
            'memindai seratus ribu sel dengan cepat; pencarian tanpa pruning '
            'mencoba ulang jalur buntu berkali kali.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

