import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('harian dengan loncatan', () {
    expect(
      jadwal('harian:2', '2026-03-01', '2026-03-07'),
      equals(['2026-03-01', '2026-03-03', '2026-03-05', '2026-03-07']),
      reason: 'Hitung dari tanggal mulai lalu tambah 2 hari tiap langkah.',
    );
    expect(
      jadwal('harian', '2026-03-01', '2026-03-03'),
      equals(['2026-03-01', '2026-03-02', '2026-03-03']),
      reason: 'Aturan harian tanpa angka berarti setiap hari.',
    );
    expect(
      jadwal('harian:3', '2026-03-01', '2026-03-09'),
      equals(['2026-03-01', '2026-03-04', '2026-03-07']),
      reason: 'Langkah 3 hari: 1, 4, 7; tanggal 10 sudah lewat batas.',
    );
  });

  test('mingguan memilih hari yang diminta', () {
    expect(
      jadwal('mingguan:senin', '2026-03-01', '2026-03-20'),
      equals(['2026-03-02', '2026-03-09', '2026-03-16']),
      reason: 'Maret 2026: hari Senin jatuh pada 2, 9, dan 16.',
    );
    expect(
      jadwal('mingguan:senin,kamis', '2026-03-01', '2026-03-13'),
      equals(['2026-03-02', '2026-03-05', '2026-03-09', '2026-03-12']),
      reason: 'Kamis 5 dan 12 ikut muncul karena keduanya diminta.',
    );
    expect(
      jadwal('mingguan:minggu', '2026-03-01', '2026-03-08'),
      equals(['2026-03-01', '2026-03-08']),
      reason: 'Batas rentang ikut dihitung bila harinya cocok.',
    );
  });

  test('bulanan melewati tanggal yang tidak ada', () {
    expect(
      jadwal('bulanan:31', '2026-03-01', '2026-06-30'),
      equals(['2026-03-31', '2026-05-31']),
      reason: 'April dan Juni tidak punya tanggal 31 jadi dilewati saja.',
    );
    expect(
      jadwal('bulanan:29', '2026-01-01', '2026-03-31'),
      equals(['2026-01-29', '2026-03-29']),
      reason: 'Februari 2026 hanya 28 hari sehingga tanggal 29 dilewati.',
    );
    expect(
      jadwal('bulanan:1,15', '2026-03-01', '2026-04-30'),
      equals(['2026-03-01', '2026-03-15', '2026-04-01', '2026-04-15']),
      reason: 'Setiap bulan menghasilkan tanggal 1 lalu 15 secara berurutan.',
    );
  });

  test('rentang terbalik menghasilkan daftar kosong', () {
    expect(
      jadwal('harian', '2026-03-10', '2026-03-01'),
      isEmpty,
      reason: 'Tanggal sampai lebih awal berarti hasilnya daftar kosong.',
    );
    expect(
      jadwal('mingguan:senin', '2026-03-20', '2026-03-01'),
      equals([]),
      reason: 'Aturan mingguan pun tetap mengembalikan daftar kosong.',
    );
    expect(
      jadwal('bulanan:akhir', '2028-03-05', '2028-01-15'),
      hasLength(0),
      reason: 'Rentang terbalik bukan kesalahan jadi daftarnya kosong.',
    );
  });

  test('masukan yang tidak sah ditolak', () {
    expect(
