    );
    expect(
      saring(data, 'nilai = 70'),
      equals([1]),
      reason: 'Tanda sama dengan cocok dengan angka yang persis sama.',
    );
  });

  test('teks dalam kutip dan penyangkalan sederhana', () {
    final data = [
      {'jurusan': 'TI', 'lulus': true},
      {'jurusan': 'SI', 'lulus': false},
      {'jurusan': 'TI', 'lulus': false},
    ];
    expect(
      saring(data, 'jurusan = "TI"'),
      equals([0, 2]),
      reason: 'Teks pembanding harus ditulis di dalam tanda kutip ganda.',
    );
    expect(
      saring(data, 'bukan lulus'),
      equals([1, 2]),
      reason: 'Kata bukan membalik arti sehingga baris gagal yang cocok.',
    );
    expect(
      saring(data, 'lulus'),
      equals([0]),
      reason: 'Nama kolom sendirian berarti kolom itu bernilai true.',
    );
  });

  test('gabungan dengan kurung', () {
    final data = [
      {'a': 1, 'b': 0, 'c': 3},
      {'a': 0, 'b': 2, 'c': 3},
      {'a': 1, 'b': 0, 'c': 0},
      {'a': 0, 'b': 0, 'c': 3},
    ];
    expect(
      saring(data, '(a = 1 atau b = 2) dan c = 3'),
      equals([0, 1]),
      reason: 'Kurung dikerjakan dulu baru hasilnya digabung dengan dan.',
    );
    final data2 = [
      {'nilai': 90, 'jurusan': 'TI'},
      {'nilai': 90, 'jurusan': 'SI'},
      {'nilai': 70, 'jurusan': 'TI'},
    ];
    expect(
      saring(data2, 'nilai > 80 dan jurusan = "TI"'),
      equals([0]),
      reason: 'Kata dan hanya cocok bila kedua syarat terpenuhi.',
    );
    expect(
      saring(data2, 'jurusan = "TI" atau jurusan = "SI"'),
      equals([0, 1, 2]),
      reason: 'Kata atau cocok bila salah satu syarat terpenuhi.',
    );
  });

  test('kolom yang tidak ada tidak pernah cocok', () {
    final data = [
      {'umur': 20},
      {'nilai': 90},
      {'nilai': 80},
    ];
    expect(
      saring(data, 'nilai != 90'),
      equals([2]),
      reason: 'Baris tanpa kolom nilai tetap tidak cocok walau memakai tidak sama dengan.',
    );
    expect(
      saring(data, 'bukan nilai != 90'),
      equals([0, 1]),
      reason: 'Kata bukan membalik hasil sehingga baris yang tadinya gagal jadi cocok.',
    );
    expect(
      saring([
        {'nilai': 'besar'},
        {'nilai': 90},
      ], 'nilai > 80'),
      equals([1]),
      reason: 'Pembanding lebih dari hanya berlaku untuk angka bukan teks.',
    );
  });

  test('kueri rusak ditolak', () {
    expect(
      () => saring([
        {'a': 1},
      ], ''),
      throwsFormatException,
      reason: 'Kueri kosong tidak punya arti sehingga harus ditolak.',
    );
    expect(
      () => saring([
        {'a': 1},
      ], '(a = 1'),
      throwsFormatException,
      reason: 'Kurung buka tanpa pasangan penutup harus ditolak.',
    );
    expect(
      () => saring([
        {'a': 1},
      ], 'a = 1 dan'),
      throwsFormatException,
      reason: 'Kata dan di ujung tanpa lanjutan berarti kueri menggantung.',
    );
  });

  test('urutan dan lebih kuat daripada atau', () {
    final data = [
      {'a': 1, 'b': 9, 'c': 9},
      {'a': 0, 'b': 2, 'c': 3},
      {'a': 0, 'b': 2, 'c': 0},
    ];
    expect(
      saring(data, 'a = 1 atau b = 2 dan c = 3'),
      equals([0, 1]),
      reason: 'Bagian dan dihitung dulu menjadi a atau (b dan c).',
    );
    expect(
      saring(data, '(a = 1 atau b = 2) dan c = 3'),
      equals([1]),
      reason: 'Kurung memaksa atau dihitung dulu sehingga baris 0 gugur.',
    );
    expect(
      saring(data, 'a = 1'),
      equals([0]),
      reason: 'Hanya baris 0 yang kolom a-nya bernilai satu.',
    );
  });

  test('bukan berlapis dan bukan atas kelompok', () {
    final data = [
      {'lulus': true},
      {'lulus': false},
    ];
    expect(
      saring(data, 'bukan bukan lulus'),
      equals([0]),
      reason: 'Dua kata bukan yang berlapis saling membatalkan artinya.',
    );
    final data2 = [
      {'a': 1, 'b': 0},
      {'a': 0, 'b': 2},
      {'a': 0, 'b': 0},
    ];
    expect(
      saring(data2, 'bukan (a = 1 atau b = 2)'),
      equals([2]),
      reason: 'Kata bukan di depan kurung membalik seluruh isi kelompok.',
    );
    expect(
      saring(data2, 'bukan a = 1'),
      equals([1, 2]),
      reason: 'Kata bukan berlaku untuk syarat yang tepat di belakangnya.',
    );
  });
}

