          ['X', 'O', 'X'],
        ]));
  });

  test('papan kosong tetap kosong', () {
    final papan = <List<String>>[];
    final ref = papan;
    kepungWilayah(papan);
    expect(identical(ref, papan), isTrue);
    expect(papan, equals([]));
  });

  test('koridor ke tepi selamatkan dalam', () {
    final papan = [
      ['X', 'X', 'X', 'X'],
      ['X', 'O', 'O', 'X'],
      ['X', 'X', 'O', 'X'],
      ['X', 'X', 'O', 'X'],
    ];
    kepungWilayah(papan);
    expect(
        papan,
        equals([
          ['X', 'X', 'X', 'X'],
          ['X', 'O', 'O', 'X'],
          ['X', 'X', 'O', 'X'],
          ['X', 'X', 'O', 'X'],
        ]),
        reason: 'Saran: gugus dalam yang punya koridor O ke tepi ikut selamat.');
  });

  test('satu baris semua bertahan', () {
    final papan = [
      ['X', 'O', 'O', 'X'],
    ];
    kepungWilayah(papan);
    expect(
        papan,
        equals([
          ['X', 'O', 'O', 'X'],
        ]),
        reason: 'Saran: pada satu baris semua sel adalah sel tepi.');
  });

  test('performa papan tiga ratus enam belas', () {
    final papan = List<List<String>>.generate(
        316, (r) => List<String>.generate(316, (c) => (r == 0 || r == 315 || c == 0 || c == 315) ? 'X' : 'O'));
    kepungWilayah(papan);
    final harap = List<List<String>>.generate(
        316, (_) => List<String>.filled(316, 'X'));
    expect(papan, equals(harap),
        reason: 'Tandai dari tepi tiap sel diproses sekali sehingga O(mn); '
            'cara periksa tiap gugus satu per satu berulang kali '
            'menelusuri ulang sel yang sama.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

