import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('masuk dan keluar dengan satu harga', () {
    expect(
      stok(['masuk 10 @ 1500', 'keluar 4']),
      equals({'sisa': 6, 'nilai': 9000, 'hpp': 6000, 'rata': 1500}),
      reason: 'Contoh dasar satu harga harus pas, cek sisa nilai hpp dan rata sekaligus.',
    );
    expect(
      stok(['masuk 3 @ 500']),
      equals({'sisa': 3, 'nilai': 1500, 'hpp': 0, 'rata': 500}),
      reason: 'Tanpa keluar hpp nol dan rata sama dengan harga, cek kasus tanpa transaksi keluar.',
    );
    expect(
      stok(['masuk 5 @ 1000', 'masuk 5 @ 1000', 'keluar 7']),
      equals({'sisa': 3, 'nilai': 3000, 'hpp': 7000, 'rata': 1000}),
      reason: 'Dua lapisan harga sama tetap FIFO, cek lapisan seharga digabung dengan benar.',
    );
  });
  test('keluar melintasi beberapa lapisan harga', () {
    expect(
      stok(['masuk 5 @ 1000', 'masuk 5 @ 2000', 'keluar 7']),
      equals({'sisa': 3, 'nilai': 6000, 'hpp': 9000, 'rata': 2000}),
      reason: 'Contoh brief lintas dua harga harus pas, ambil dulu dari lapisan paling lama.',
    );
    expect(
      stok(['masuk 2 @ 100', 'masuk 3 @ 200', 'masuk 4 @ 300', 'keluar 6']),
      equals({'sisa': 3, 'nilai': 900, 'hpp': 1100, 'rata': 300}),
      reason: 'Keluar melintasi tiga lapisan, cek hpp menjumlah tiap potongan harga.',
    );
    expect(
      stok(['masuk 1 @ 5', 'masuk 1 @ 7', 'keluar 1']),
      equals({'sisa': 1, 'nilai': 7, 'hpp': 5, 'rata': 7}),
      reason: 'Keluar satu dari dua lapisan, yang sisa lapisan termuda jadi cek urutan FIFO.',
    );
  });
  test('keluar sampai habis', () {
    expect(
      stok(['masuk 4 @ 250', 'keluar 4']),
      equals({'sisa': 0, 'nilai': 0, 'hpp': 1000, 'rata': 0}),
      reason: 'Stok habis berarti sisa dan nilai nol, rata ikut nol bukan error bagi nol.',
    );
    expect(
      stok(['masuk 2 @ 100', 'masuk 3 @ 200', 'keluar 5']),
      equals({'sisa': 0, 'nilai': 0, 'hpp': 800, 'rata': 0}),
      reason: 'Habis lintas harga hpp tetap penuh, cek semua lapisan terkuras.',
    );
    expect(
      stok(['masuk 2 @ 100', 'keluar 2', 'masuk 3 @ 400']),
      equals({'sisa': 3, 'nilai': 1200, 'hpp': 200, 'rata': 400}),
      reason: 'Masuk lagi setelah habis mulai dari nol, cek gudang bisa diisi ulang.',
    );
  });
  test('keluar melebihi stok ditolak', () {
    expect(
      () => stok(['masuk 3 @ 100', 'keluar 4']),
      throwsFormatException,
      reason:
          'Keluar lebih dari stok tidak sah, harus melempar FormatException.',
    );
    expect(
      () => stok(['keluar 1']),
      throwsFormatException,
      reason: 'Gudang kosong tak bisa mengeluarkan apa pun, harus melempar FormatException.',
    );
    expect(
      () => stok(['masuk 2 @ 50', 'keluar 2', 'keluar 1']),
      throwsFormatException,
      reason: 'Keluar kedua setelah stok habis tetap ditolak, cek tiap baris divalidasi.',
    );
  });
  test('baris yang tidak dikenal ditolak', () {
    expect(
      () => stok(['tambah 5 @ 100']),
      throwsFormatException,
      reason: 'Kata kerja asing tidak dikenal, harus melempar FormatException.',
    );
    expect(
      () => stok(['masuk 0 @ 100']),
      throwsFormatException,
      reason:
          'Jumlah nol bukan bilangan positif, harus melempar FormatException.',
    );
    expect(
      () => stok(['masuk 5 @ 0']),
      throwsFormatException,
      reason:
          'Harga nol bukan bilangan positif, harus melempar FormatException.',
    );
    expect(
      () => stok(['keluar']),
      throwsFormatException,
      reason: 'Baris tak lengkap tanpa jumlah tidak sah, harus melempar FormatException.',
    );
  });
  test('retur mengembalikan barang ke harga asalnya', () {
    expect(
      stok(['masuk 5 @ 1000', 'masuk 5 @ 2000', 'keluar 7', 'retur 2']),
      equals({'sisa': 5, 'nilai': 10000, 'hpp': 5000, 'rata': 2000}),
      reason: 'Dua barang termuda kembali ke depan, cek hpp berkurang sebesar harganya.',
    );
    expect(
      stok([
        'masuk 5 @ 1000',
        'masuk 5 @ 2000',
        'keluar 7',
        'retur 2',
        'keluar 3',
      ]),
      equals({'sisa': 2, 'nilai': 4000, 'hpp': 11000, 'rata': 2000}),
      reason: 'Keluar setelah retur ambil barang returan dulu, cek antrean depan terisi.',
    );
    expect(
      () => stok(['masuk 5 @ 100', 'keluar 3', 'retur 4']),
      throwsFormatException,
      reason: 'Retur melebihi yang pernah keluar tidak sah, harus melempar FormatException.',
    );
  });
  test('harga rata-rata sisa dibulatkan ke bawah', () {
    expect(
      stok(['masuk 3 @ 100', 'masuk 1 @ 103', 'keluar 2']),
      equals({'sisa': 2, 'nilai': 203, 'hpp': 200, 'rata': 101}),
      reason: 'Rata 203 bagi 2 dibulatkan ke bawah jadi 101, cek pembagian bulat ke bawah.',
    );
    expect(
      stok(['masuk 2 @ 1000', 'masuk 2 @ 1001', 'keluar 1'])['rata'],
      equals(1000),
      reason: 'Rata 3002 bagi 3 jatuh ke 1000, cek sisa pembagian dibuang.',
    );
    expect(
      stok(['masuk 1 @ 5', 'keluar 1'])['rata'],
      equals(0),
      reason: 'Sisa nol rata nol bukan error, cek penjagaan bagi nol.',
    );
  });
}

