import 'package:test/test.dart';
import 'package:latih/solusi.dart';

List<List<int>> _urut(List<List<int>> sel) {
  sel.sort((a, b) => a[0] == b[0] ? a[1].compareTo(b[1]) : a[0].compareTo(b[0]));
  return sel;
}

void main() {
  test('contoh dua kali dua tiga sel', () {
    expect(
        _urut(aliranSamudra([
          [1, 2],
          [3, 4],
        ])),
        equals([
          [0, 1],
          [1, 0],
          [1, 1],
        ]));
  });

  test('satu sel mengalir dua samudra', () {
    expect(
        _urut(aliranSamudra([
          [1],
        ])),
        equals([
          [0, 0],
        ]));
  });

  test('satu baris semua mengalir', () {
    expect(
        _urut(aliranSamudra([
          [1, 2, 3],
        ])),
        equals([
          [0, 0],
          [0, 1],
          [0, 2],
        ]));
  });

  test('semua sama tinggi semua sel', () {
    expect(
        _urut(aliranSamudra([
          [2, 2],
          [2, 2],
        ])),
        equals([
          [0, 0],
          [0, 1],
          [1, 0],
          [1, 1],
        ]));
  });

  test('cekungan tengah kecuali tengah', () {
    expect(
        _urut(aliranSamudra([
          [5, 5, 5],
          [5, 1, 5],
          [5, 5, 5],
        ])),
        equals([
          [0, 0],
          [0, 1],
          [0, 2],
          [1, 0],
          [1, 2],
          [2, 0],
          [2, 1],
          [2, 2],
        ]));
  });

  test('satu kolom semua mengalir', () {
    expect(
        _urut(aliranSamudra([
          [1],
          [2],
          [3],
        ])),
        equals([
          [0, 0],
          [1, 0],
          [2, 0],
        ]),
        reason: 'Saran: tiap sel satu kolom menyentuh tepi kiri dan kanan.');
  });

  test('puncak tengah mengalir ke mana pun', () {
    expect(
        _urut(aliranSamudra([
          [1, 1, 1],
          [1, 5, 1],
          [1, 1, 1],
        ])),
        equals([
          [0, 0],
          [0, 1],
          [0, 2],
          [1, 0],
          [1, 1],
          [1, 2],
          [2, 0],
          [2, 1],
          [2, 2],
        ]),
        reason: 'Saran: sel tertinggi mengalir turun ke semua sisi.');
  });

  test('performa lembah tepi tiga ratus enam belas', () {
    int jarak(int r, int c) {
      var d = r;
      if (315 - r < d) d = 315 - r;
      if (c < d) d = c;
      if (315 - c < d) d = 315 - c;
      return d;
    }

    final tinggi = List<List<int>>.generate(
        316, (r) => List<int>.generate(316, (c) => jarak(r, c)));
    final hasil = aliranSamudra(tinggi);
    expect(hasil.length, greaterThan(1000),
        reason: 'Dua rambatan tepi tiap sel dikunjungi dua kali '
            'sehingga O(mn); cara alirkan tiap sel satu per satu '
            'mengulang telusur yang sama berkali kali.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

