      ['E', 'M'],
      ['E', 'E'],
    ];
    expect(
        bukaMinesweeper(papan, [0, 1]),
        equals([
          ['E', 'X'],
          ['E', 'E'],
        ]));
  });

  test('klik kosong satu tetangga ranjau', () {
    final papan = [
      ['E', 'M'],
      ['E', 'E'],
    ];
    expect(
        bukaMinesweeper(papan, [0, 0]),
        equals([
          ['1', 'M'],
          ['E', 'E'],
        ]));
  });

  test('banjir kosong berhenti di bingkai angka', () {
    final papan = [
      ['E', 'E', 'E'],
      ['E', 'E', 'E'],
      ['E', 'E', 'M'],
    ];
    expect(
        bukaMinesweeper(papan, [0, 0]),
        equals([
          ['B', 'B', 'B'],
          ['B', '1', '1'],
          ['B', '1', 'M'],
        ]));
  });

  test('papan satu kali satu kosong terbuka', () {
