        ]));
  });

  test('banjir empat kali empat satu ranjau sudut', () {
    final papan = List.generate(4, (_) => List.filled(4, 'E'));
    papan[3][3] = 'M';
    final hasil = bukaMinesweeper(papan, [0, 0]);
    expect(hasil[0][0], equals('B'),
        reason: 'Sel jauh dari ranjau membuka tanpa angka.');
    expect(hasil[2][2], equals('1'),
        reason: 'Sel di samping ranjau sudut menulis angka satu.');
    expect(hasil[3][3], equals('M'),
        reason: 'Ranjau yang tidak diklik tetap tertutup.');
  });

  test('klik sel terbuka tidak mengubah papan', () {
