      ['B', '1', 'E'],
      ['B', '1', 'E'],
      ['B', '1', 'M'],
    ];
    expect(bukaMinesweeper(papan, [0, 0]), equals(papan),
        reason: 'Klik sel B yang sudah terbuka tidak membuka sel baru.');
    expect(bukaMinesweeper(papan, [0, 1]), equals(papan),
        reason: 'Klik sel angka tidak memicu banjir baru.');
  });

  test('performa tiga ratus enam belas kali tiga ratus enam belas', () {
    final papan = List.generate(316, (_) => List.filled(316, 'E'));
    papan[315][315] = 'M';
    final hasil = bukaMinesweeper(papan, [0, 0]);
    expect(hasil[0][0], equals('B'),
