            'kali kolom); buka ulang tetangga tanpa tanda kunjungi '
            'mengulang kerja sampai puluhan miliar langkah.');
    expect(hasil[314][314], equals('1'));
  }, timeout: Timeout(Duration(seconds: 30)));
}

