test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

List<List<int>> _rapi(List<List<int>> gabungan) {
  final salin = gabungan.map((e) => List<int>.from(e)..sort()).toList();
  salin.sort((a, b) {
    if (a.length != b.length) {
      return a.length.compareTo(b.length);
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return a[i].compareTo(b[i]);
      }
    }
    return 0;
  });
  return salin;
}

void main() {
  test('contoh dua jawaban target tujuh', () {
    expect(
        _rapi(jumlahKombinasi([2, 3, 6, 7], 7)),
        equals([
          [7],
          [2, 2, 3],
        ]));
  });

  test('tiga jawaban target delapan', () {
    expect(
        _rapi(jumlahKombinasi([2, 3, 5], 8)),
        equals([
          [3, 5],
          [2, 3, 3],
          [2, 2, 2, 2],
        ]));
  });

  test('target tak tercapai kosong', () {
    expect(jumlahKombinasi([2], 1), isEmpty);
  });

  test('satu pecahan dirangkai ulang', () {
    expect(
        _rapi(jumlahKombinasi([1], 2)),
        equals([
          [1, 1],
        ]));
  });

  test('satu kandidat pas target', () {
    expect(
        _rapi(jumlahKombinasi([2, 5], 10)),
        equals([
          [5, 5],
          [2, 2, 2, 2, 2],
        ]),
        reason: 'Kandidat yang pas target jadi jawaban sendiri, '
            'sisa kombinasi disusun dari pecahan yang lebih kecil.');
  });

  test('kandidat duplikat tanpa jawaban ganda', () {
    expect(
        _rapi(jumlahKombinasi([2, 2, 3], 7)),
        equals([
          [2, 2, 3],
        ]),
        reason: 'Nilai kandidat yang sama tidak boleh melahirkan '
            'kombinasi kembar.');
  });

  test('performa tiga pecahan target tiga puluh', () {
    final hasil = _rapi(jumlahKombinasi([2, 3, 5], 30));
    expect(hasil.length, equals(21),
        reason: 'Susun mundur dari indeks dengan henti awal butuh langkah '
            'sebanding hasil; coba semua urutan tanpa batas indeks '
            'melahirkan permutasi ganda dan kerja jauh lebih besar.');
    for (final gab in hasil) {
      expect(gab.reduce((a, b) => a + b), equals(30));
    }
  }, timeout: Timeout(Duration(seconds: 30)));
}

