/// Mengembalikan SATU substring palindrom terpanjang dari [s].
///
/// Bila ada beberapa jawaban sama panjang, kembalikan salah satu saja.
/// Untuk string kosong, jawabannya string kosong.
String palindromTerpanjang(String s) {
  // TODO: kerjakan di sini
  return s.isEmpty ? '' : s[0];
}

test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

bool _palindrom(String t) {
  var kiri = 0;
  var kanan = t.length - 1;
  while (kiri < kanan) {
    if (t[kiri] != t[kanan]) {
      return false;
    }
    kiri++;
    kanan--;
  }
  return true;
}

void _cekSah(String s, String hasil, int panjang, String alasan) {
  expect(hasil.length, equals(panjang), reason: alasan);
  expect(_palindrom(hasil), isTrue, reason: alasan);
  expect(s.contains(hasil), isTrue, reason: alasan);
}

void main() {
  test('contoh cbbd jawab bb', () {
    final hasil = palindromTerpanjang('cbbd');
    expect(hasil.length, equals(2));
    expect(_palindrom(hasil), isTrue);
    expect('cbbd'.contains(hasil), isTrue);
  });

  test('seluruh kata racecar palindrom', () {
    expect(palindromTerpanjang('racecar'), equals('racecar'));
  });

  test('satu huruf jawab dirinya', () {
    expect(palindromTerpanjang('a'), equals('a'));
  });

  test('string kosong jawab kosong', () {
    expect(palindromTerpanjang(''), equals(''));
  });

  test('seri babad terima bab atau aba', () {
    _cekSah('babad', palindromTerpanjang('babad'), 3,
        'Bila seri, "bab" atau "aba" sama sah; yang penting panjang tiga, '
        'palindrom, dan potongan dari masukan.');
  });

  test('tanpa palindrom panjang jawab satu huruf', () {
    _cekSah('abcde', palindromTerpanjang('abcde'), 1,
        'Tanpa huruf berulang tidak ada palindrom di atas satu huruf; '
        'jawaban satu huruf mana pun sah.');
  });

  test('palindrom genap di tengah kata', () {
    _cekSah('forgeeksskeegfor', palindromTerpanjang('forgeeksskeegfor'), 10,
        'Jangan lupa tengah genap di celah antar huruf; "geeksskeeg" '
        'panjang sepuluh hanya ketemu lewat celah tengah.');
  });

  test('performa palindrom raksasa empat ribu', () {
    final s = 'a' * 2000 + 'b' + 'a' * 2000;
    expect(palindromTerpanjang(s), equals(s),
        reason: 'Perluas dari tiap tengah butuh sekitar n kuadrat langkah; '
            'coba semua substring lalu uji palindrom butuh n pangkat tiga '
            'dan tewas pada n empat ribu.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

