    expect((Pecahan(1, 2) - Pecahan(3, 4)).toString(), '-1/4');
    expect((Pecahan(5, 6) - Pecahan(1, 6)).toString(), '2/3');
  });

  test('kali dan bagi pecahan', () {
    expect((Pecahan(2, 3) * Pecahan(3, 4)).toString(), '1/2');
    expect((Pecahan(1, 2) / Pecahan(3, 4)).toString(), '2/3');
    expect((Pecahan(-1, 2) * Pecahan(2, 3)).toString(), '-1/3');
  });

