        reason: 'Penyebut negatif harus dinormalkan: kalikan pembilang '
            'dan penyebut dengan -1 di konstruktor.');
    expect(Pecahan(-2, -5).toString(), '2/5',
        reason: 'Dua tanda negatif saling meniadakan menjadi pecahan positif.');
    expect(Pecahan(0, -7).toString(), '0/1',
        reason: 'Nol tetap nol dalam bentuk paling sederhana.');
  });
}

