import 'package:test/test.dart';
import 'package:latih/solusi.dart';

bool _sah51(String hasil, List<String> kata) {
  final huruf = <String>{};
  for (final k in kata) {
    huruf.addAll(k.split(''));
  }
  if (hasil.length != huruf.length) {
    return false;
  }
  if (hasil.split('').toSet().length != hasil.length) {
    return false;
  }
  for (final h in hasil.split('')) {
    if (!huruf.contains(h)) {
      return false;
    }
  }
  final posisi = <String, int>{};
  for (var i = 0; i < hasil.length; i++) {
    posisi[hasil[i]] = i;
  }
  bool urut(String a, String b) {
    final n = a.length < b.length ? a.length : b.length;
    for (var i = 0; i < n; i++) {
      if (a[i] != b[i]) {
        return posisi[a[i]]! < posisi[b[i]]!;
      }
    }
    return a.length <= b.length;
  }
  for (var i = 0; i + 1 < kata.length; i++) {
    if (!urut(kata[i], kata[i + 1])) {
      return false;
    }
  }
  return true;
}

void main() {
  test('contoh lima kata urutan wertf', () {
    expect(
        urutanHuruf(['wrt', 'wrf', 'er', 'ett', 'rftt']), equals('wertf'));
  });

  test('dua kata dua huruf', () {
    expect(urutanHuruf(['z', 'x']), equals('zx'));
  });

  test('siklus kembali kosong', () {
    expect(urutanHuruf(['z', 'x', 'z']), isEmpty);
  });

  test('prefiks invalid kosong', () {
    expect(urutanHuruf(['abc', 'ab']), isEmpty);
  });

  test('daftar kosong hasil kosong', () {
    expect(urutanHuruf([]), isEmpty);
  });

  test('satu kata semua huruf muncul sekali', () {
    final hasil = urutanHuruf(['kunci']);
    expect(_sah51(hasil, ['kunci']), isTrue,
        reason: 'Saran: satu kata bebas urutannya, tapi tiap hurufnya '
            'harus muncul tepat sekali.');
  });

  test('performa tiga puluh ribu kata berpola', () {
    final kata = <String>[];
    const abjad = 'abcdefgh';
    var bibit = 7;
    for (var i = 0; i < 30000; i++) {
      bibit = (bibit * 1103515245 + 12345) & 0x7fffffff;
      final panjang = 3 + (bibit % 5);
      final sb = StringBuffer();
      var sisa = bibit;
      for (var j = 0; j < panjang; j++) {
        sb.write(abjad[sisa % abjad.length]);
        sisa = sisa ~/ abjad.length + j;
      }
      kata.add(sb.toString());
    }
    kata.sort();
    final hasil = urutanHuruf(kata);
    expect(_sah51(hasil, kata), isTrue,
        reason: 'Banding pasangan berdampingan saja butuh langkah '
            'sebanding total huruf; banding semua pasangan butuh sekitar '
            'kata kuadrat dan tidak selesai tepat waktu.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

brief:
# MD-51, Total ukuran folder secara rekursif

Tulis fungsi `totalUkuran` yang menjumlahkan ukuran seluruh berkas dalam struktur folder bersarang.

## Kontrak

```dart
int totalUkuran(Berkas node);
```

dengan tipe node sebagai berikut (tipe ini sudah disediakan, jangan ditulis ulang):

```dart
sealed class Berkas {
  const Berkas();
}

final class File extends Berkas {
  const File(this.ukuran);
  final int ukuran;
}

final class Folder extends Berkas {
  const Folder(this.isi);
  final List<Berkas> isi;
}
```

## Yang harus dipenuhi

- `File` menyumbang ukurannya sendiri.
- `Folder` menyumbang jumlah total seluruh isinya, dijumlahkan secara rekursif sampai ke berkas paling dalam.
- `Folder` kosong menyumbang 0.
- Ukuran negatif melempar `ArgumentError`. Periksa tiap `File` yang dikunjungi, di kedalaman berapa pun.
- Selesaikan dengan rekursi dan switch atas `Berkas`, bukan dengan perulangan manual memakai tumpukan sendiri.

## Contoh

| Masukan                                                                 | Hasil                    |
| ----------------------------------------------------------------------- | ------------------------ |
| `totalUkuran(File(100))`                                                | `100`                    |
| `totalUkuran(Folder([]))`                                               | `0`                      |
| `totalUkuran(Folder([File(10), File(20)]))`                             | `30`                     |
| `totalUkuran(Folder([File(10), Folder([File(5), Folder([File(1)])])]))` | `16`                     |
| `totalUkuran(Folder([File(-5)]))`                                       | melempar `ArgumentError` |

## Jelaskan

- Apa basis dan langkah rekursif fungsi ini?
- Kenapa switch atas sealed class cocok untuk struktur pohon seperti ini?
- Seberapa dalam tumpukan rekursi bisa tumbuh, dan kapan itu jadi masalah?

