test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('contoh klasik gusur dua lalu satu', () {
    final c = LruCache(2);
    c.simpan(1, 1);
    c.simpan(2, 2);
    expect(c.ambil(1), equals(1));
    c.simpan(3, 3);
    expect(c.ambil(2), equals(-1));
    c.simpan(4, 4);
    expect(c.ambil(1), equals(-1));
    expect(c.ambil(3), equals(3));
    expect(c.ambil(4), equals(4));
  });

  test('update nilai segarkan recency', () {
    final c = LruCache(2);
    c.simpan(1, 1);
    c.simpan(2, 2);
    c.simpan(1, 10);
    expect(c.ambil(1), equals(10));
    c.simpan(3, 3);
    expect(c.ambil(2), equals(-1));
    expect(c.ambil(1), equals(10));
  });

  test('kapasitas satu selalu gusur lama', () {
    final c = LruCache(1);
    c.simpan(5, 5);
    c.simpan(6, 6);
    expect(c.ambil(5), equals(-1));
    expect(c.ambil(6), equals(6));
  });

  test('ambil kunci hilang minus satu', () {
    final c = LruCache(2);
    c.simpan(1, 1);
    expect(c.ambil(99), equals(-1));
  });

  test('simpan kunci sama berulang tetap sah', () {
    final c = LruCache(2);
    for (var i = 0; i < 50; i++) {
      c.simpan(1, i);
    }
    expect(c.ambil(1), equals(49));
    c.simpan(2, 2);
    c.simpan(3, 3);
    expect(c.ambil(1), equals(-1),
        reason: 'Saran: tulis ulang kunci yang sama tidak menambah isi, '
            'jadi kunci 1 yang lama tergusur oleh kunci 3.');
    expect(c.ambil(3), equals(3));
  });

  test('performa seratus ribu campur acak berpola', () {
    final c = LruCache(1000);
    var bibit = 1234567;
    for (var i = 0; i < 100000; i++) {
      bibit = (bibit * 1103515245 + 12345) & 0x7fffffff;
      final kunci = bibit % 1500;
      if (i % 3 == 2) {
        c.ambil(kunci);
      } else {
        c.simpan(kunci, i);
      }
    }
    for (var k = 0; k < 1500; k++) {
      c.simpan(k, k * 2);
    }
    for (var k = 1000; k < 1500; k++) {
      expect(c.ambil(k), equals(k * 2));
    }
    expect(c.ambil(0), equals(-1),
        reason: 'Map plus list dua arah memberi tiap operasi O(1); '
            'geser list biasa tiap akses butuh O(kapasitas) dan kerja '
            'total meledak untuk seratus ribu operasi.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

