import 'package:test/test.dart';
import 'package:latih/solusi.dart';

TreeNode _rantaiKiri55(List<int> nilai) {
  TreeNode? akar;
  for (var i = nilai.length - 1; i >= 0; i--) {
    akar = TreeNode(nilai[i], akar);
  }
  return akar!;
}

TreeNode _bangunLengkap55(int n) {
  final simpul = List<TreeNode?>.generate(
    n + 1,
    (i) => i == 0 ? null : TreeNode(i),
  );
  for (var i = n; i >= 1; i--) {
    simpul[i]!.kiri = 2 * i <= n ? simpul[2 * i] : null;
    simpul[i]!.kanan = 2 * i + 1 <= n ? simpul[2 * i + 1] : null;
  }
  return simpul[1]!;
}

void main() {
  test('format sandi pohon kecil persis', () {
    final kode = KodePohon();
    final akar = TreeNode(1, TreeNode(2), TreeNode(3));
    expect(kode.sandi(akar), equals('1,2,#,#,3,#,#'));
    expect(kode.sandi(null), equals('#'));
  });

  test('roundtrip contoh campuran sama persis', () {
    final kode = KodePohon();
    final asli = TreeNode(
      1,
      TreeNode(2),
      TreeNode(3, TreeNode(4), TreeNode(5)),
    );
    final hasil = kode.buka(kode.sandi(asli))!;
    expect(kode.sandi(hasil), equals(kode.sandi(asli)));
    expect(hasil.nilai, equals(1));
    expect(hasil.kiri!.nilai, equals(2));
    expect(hasil.kanan!.nilai, equals(3));
    expect(hasil.kanan!.kiri!.nilai, equals(4));
    expect(hasil.kanan!.kanan!.nilai, equals(5));
  });

  test('pohon kosong sandi pagar buka null', () {
    final kode = KodePohon();
    expect(kode.sandi(null), equals('#'));
    expect(kode.buka('#'), isNull);
    expect(kode.buka(kode.sandi(null)), isNull);
  });

  test('satu simpul roundtrip nilai sama', () {
    final kode = KodePohon();
    expect(kode.sandi(TreeNode(7)), equals('7,#,#'));
    final hasil = kode.buka('7,#,#')!;
    expect(hasil.nilai, equals(7));
    expect(hasil.kiri, isNull);
    expect(hasil.kanan, isNull);
  });

  test('rantai kiri condong roundtrip sama', () {
    final kode = KodePohon();
    final asli = _rantaiKiri55([1, 2, 3, 4]);
    final hasil = kode.buka(kode.sandi(asli))!;
    expect(kode.sandi(hasil), equals(kode.sandi(asli)));
    var jalan = hasil;
    for (final nilai in [1, 2, 3, 4]) {
      expect(jalan.nilai, equals(nilai));
      expect(jalan.kanan, isNull);
      if (nilai < 4) {
        jalan = jalan.kiri!;
      }
    }
    expect(jalan.kiri, isNull);
  });

  test('buka lalu sandi ulang stabil', () {
    final kode = KodePohon();
    const data = '5,#,6,#,#';
    final hasil = kode.buka(data)!;
    expect(hasil.nilai, equals(5),
        reason: 'Token pertama selalu jadi akar, lalu subtree kiri '
            'dibangun sebelum subtree kanan.');
    expect(hasil.kiri, isNull,
        reason: 'Token kedua # berarti anak kiri kosong.');
    expect(hasil.kanan!.nilai, equals(6),
        reason: 'Token ketiga 6 jadi anak kanan sesudah kiri selesai.');
    expect(kode.sandi(hasil), equals(data),
        reason: 'Sandi dari pohon hasil buka harus reproduksi teks asal.');
  });

  test('performa seratus ribu simpul roundtrip', () {
    final kode = KodePohon();
    final asli = _bangunLengkap55(100000);
    final data = kode.sandi(asli);
    final hasil = kode.buka(data)!;
    expect(kode.sandi(hasil), equals(data),
        reason: 'Daftar token yang digabung sekali memberi sandi linear; '
            'tempel string dengan += tiap simpul butuh kuadrat dan tidak '
            'selesai tepat waktu.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

