import 'package:test/test.dart';
import 'package:latih/solusi.dart';

TreeNode _contoh56() {
  return TreeNode(3,
      TreeNode(5, TreeNode(6), TreeNode(2, TreeNode(7), TreeNode(4))),
      TreeNode(1, TreeNode(0), TreeNode(8)));
}

TreeNode _rantai56(int n) {
  final akar = TreeNode(0);
  var jalan = akar;
  for (var i = 1; i < n; i++) {
    jalan.kanan = TreeNode(i);
    jalan = jalan.kanan!;
  }
  return akar;
}

TreeNode _lengkap56(int n) {
  final simpul = List<TreeNode>.generate(n, (i) => TreeNode(i));
  for (var i = 0; i < n; i++) {
    final kiri = 2 * i + 1;
    final kanan = 2 * i + 2;
    if (kiri < n) simpul[i].kiri = simpul[kiri];
    if (kanan < n) simpul[i].kanan = simpul[kanan];
  }
  return simpul[0];
}

void main() {
  test('contoh lima dan satu bertemu di tiga', () {
    expect(leluhurBersama(_contoh56(), 5, 1), equals(3));
  });

  test('contoh lima dan nol bertemu di tiga', () {
    expect(leluhurBersama(_contoh56(), 5, 0), equals(3));
  });

  test('contoh enam dan dua bertemu di lima', () {
    expect(leluhurBersama(_contoh56(), 6, 2), equals(5));
  });

  test('leluhur langsung jadi jawaban', () {
    expect(leluhurBersama(_contoh56(), 5, 2), equals(5));
  });

  test('satu simpul jawab dirinya', () {
    expect(leluhurBersama(TreeNode(7), 7, 7), equals(7));
  });

  test('daun beda cabang jauh', () {
    expect(leluhurBersama(_contoh56(), 7, 8), equals(3),
        reason: 'Saran: jalur 7 naik lewat 2 dan 5, jalur 8 naik lewat 1, '
            'pertemuan pertamanya di akar 3.');
  });

  test('pohon rantai jawab leluhur dekat', () {
    final akar = _rantai56(100);
    expect(leluhurBersama(akar, 30, 70), equals(30),
        reason: 'Saran: di rantai kanan, simpul bernilai kecil adalah '
            'leluhur semua simpul bernilai besar.');
  });

  test('performa pohon lengkap seratus ribu', () {
    final akar = _lengkap56(100000);
    expect(leluhurBersama(akar, 99998, 99999), equals(1561),
        reason: 'Rekursi sekali jalan tiap simpul dikunjungi sekali '
            'sehingga O(n); menyimpan lalu membandingkan jalur tiap '
            'kueri mengulang telusur yang sama dan butuh memori ekstra.');
  }, timeout: Timeout(Duration(seconds: 30)));
}

