}

/// Menggabungkan [daftar] yang tiapnya terurut jadi satu senarai terurut.
///
/// Tiap elemen [daftar] adalah kepala satu senarai atau null bila
/// kosong. Hasil null bila tidak ada nilai sama sekali.
ListNode? gabungDaftar(List<ListNode?> daftar) {
  // TODO: kerjakan di sini
  return null;
}

test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

ListNode? _rantai59(List<int> nilai) {
  ListNode? kepala;
  for (var i = nilai.length - 1; i >= 0; i--) {
    kepala = ListNode(nilai[i], kepala);
  }
  return kepala;
}

List<int> _nilai59(ListNode? kepala) {
  final hasil = <int>[];
  var jalan = kepala;
  while (jalan != null) {
    hasil.add(jalan.nilai);
    jalan = jalan.next;
  }
  return hasil;
}

void main() {
  test('contoh tiga daftar delapan nilai', () {
    final hasil = gabungDaftar([
      _rantai59([1, 4, 5]),
      _rantai59([1, 3, 4]),
      _rantai59([2, 6]),
    ]);
    expect(_nilai59(hasil), equals([1, 1, 2, 3, 4, 4, 5, 6]));
  });

  test('tanpa daftar hasil null', () {
    expect(gabungDaftar([]), isNull);
  });

  test('satu daftar kosong hasil null', () {
    expect(gabungDaftar([null]), isNull);
  });

  test('negatif dan pendek gabung urut', () {
    final hasil = gabungDaftar([
      _rantai59([-2, -1]),
      _rantai59([0]),
      _rantai59([1]),
    ]);
    expect(_nilai59(hasil), equals([-2, -1, 0, 1]));
  });

  test('null campur daftar isi', () {
    final hasil = gabungDaftar([
      null,
      _rantai59([2, 3]),
      null,
      _rantai59([1]),
    ]);
    expect(_nilai59(hasil), equals([1, 2, 3]),
        reason: 'Saran: kepala null dilewati, hanya daftar berisi '
            'yang masuk heap.');
  });

  test('seribu daftar satu nilai', () {
    final daftar = List<ListNode?>.generate(
        1000, (i) => _rantai59([1000 - i]));
    expect(_nilai59(gabungDaftar(daftar)),
        equals(List<int>.generate(1000, (i) => i + 1)),
        reason: 'Saran: heap berisi k kepala lalu tiap langkah '
            'mengeluarkan yang terkecil, bukan menggabung berpasangan.');
  });

  test('performa seribu daftar seratus nilai', () {
    final daftar = List<ListNode?>.generate(1000, (i) {
      return _rantai59(List<int>.generate(100, (j) => i + j * 1000));
    });
    final hasil = _nilai59(gabungDaftar(daftar));
    expect(hasil.length, equals(100000));
    expect(hasil.first, equals(0));
    expect(hasil.last, equals(99999),
        reason: 'Heap k kepala memberi total n log k; gabung satu per '
            'satu dari depan mengulang daftar yang sama sampai '
            'sekitar k kali lipat.');
    for (var i = 1; i < hasil.length; i++) {
      expect(hasil[i] >= hasil[i - 1], isTrue);
    }
  }, timeout: Timeout(Duration(seconds: 30)));
}

