test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

List<int> _rapi60(List<int> angka) {
  return List<int>.from(angka)..sort();
}

void main() {
  test('contoh dua teratas', () {
    expect(_rapi60(seringMuncul([1, 1, 1, 2, 2, 3], 2)), equals([1, 2]));
  });

  test('satu angka satu teratas', () {
    expect(seringMuncul([1], 1), equals([1]));
  });

  test('seri dua teratas', () {
    expect(_rapi60(seringMuncul([4, 4, 5, 5, 6], 2)), equals([4, 5]));
  });

  test('k nol hasil kosong', () {
    expect(seringMuncul([7, 8, 9], 0), isEmpty);
  });

  test('list kosong hasil kosong', () {
    expect(seringMuncul([], 3), isEmpty);
  });

  test('k lebih dari variasi semua keluar', () {
    expect(_rapi60(seringMuncul([2, 2, 9], 5)), equals([2, 9]),
        reason: 'Saran: hanya ada dua angka berbeda, keduanya '
            'dikembalikan walau k meminta lima.');
  });

  test('seri di batas k sah mana pun', () {
    final hasil = seringMuncul([1, 2, 2, 3, 3, 4], 2);
    expect(hasil.length, equals(2),
        reason: 'Saran: tepat dua barang dikembalikan.');
    expect(hasil.toSet().length, equals(2),
        reason: 'Saran: tidak ada barang ganda di jawaban.');
    expect(hasil.contains(2) || hasil.contains(3), isTrue,
        reason: 'Saran: 2 dan 3 sama-sama frekuensi dua, jawaban sah '
            'memuat salah satunya.');
  });

  test('performa seratus ribu angka', () {
    final angka = <int>[];
    for (var i = 0; i < 50000; i++) {
      angka.add(i % 1000);
    }
    for (var i = 0; i < 50000; i++) {
      angka.add(1000 + i);
    }
    final hasil = seringMuncul(angka, 5);
    expect(hasil.length, equals(5));
    expect(hasil.toSet().length, equals(5));
    for (final x in hasil) {
      expect(x >= 0 && x < 1000, isTrue,
          reason: 'Ember frekuensi memungut jawaban dalam waktu linear; '
              'mengurutkan semua pasangan frekuensi butuh n log n '
              'dan jauh lebih lambat.');
    }
  }, timeout: Timeout(Duration(seconds: 30)));
}

