test:
import 'package:test/test.dart';
import 'package:latih/solusi.dart';

void main() {
  test('nol sampai dua baris', () {
    expect(segitigaPascal(0), isEmpty);
    expect(segitigaPascal(1), [
      [1]
    ]);
    expect(segitigaPascal(2), [
      [1],
      [1, 1]
    ]);
  });

  test('lima baris pertama', () {
    expect(segitigaPascal(5), [
      [1],
      [1, 1],
      [1, 2, 1],
      [1, 3, 3, 1],
      [1, 4, 6, 4, 1],
    ]);
  });

  test('baris keenam dan kesepuluh', () {
    expect(segitigaPascal(6).last, [1, 5, 10, 10, 5, 1]);
    expect(segitigaPascal(10).last, [1, 9, 36, 84, 126, 126, 84, 36, 9, 1]);
    expect(segitigaPascal(10).length, 10);
  });

  test('tiap baris simetris', () {
    final hasil = segitigaPascal(9);
    for (final baris in hasil) {
      expect(baris, baris.reversed.toList());
    }
    expect(hasil.length, 9);
  });

  test('jumlah baris adalah pangkat dua', () {
    final hasil = segitigaPascal(12);
    var pangkat = 1;
    for (var n = 0; n < hasil.length; n++) {
      final jumlah = hasil[n].reduce((a, b) => a + b);
      expect(jumlah, pangkat);
      pangkat *= 2;
    }
  });

  test('baris berdiri sendiri', () {
    final hasil = segitigaPascal(5);
    hasil[2][1] = 99;
    expect(hasil[3], [1, 3, 3, 1],
        reason: 'Mengubah baris ketiga tidak boleh merembet ke baris keempat.');
    expect(hasil[2], [1, 99, 1],
        reason: 'Hanya baris yang diubah yang berubah.');
  });

  test('di luar rentang melempar ArgumentError', () {
    expect(() => segitigaPascal(-1), throwsArgumentError,
        reason: 'Baris negatif tidak punya arti.');
    expect(() => segitigaPascal(31), throwsArgumentError,
        reason: 'Kontrak membatasi sampai 30 baris.');
    expect(segitigaPascal(30).length, 30,
        reason: 'Batas atas sendiri tetap sah.');
  });
}
